"""Textes du Port, morceau 2 : étapes P6 à P11 (dit, bravo, version des grands)."""
L = ["fr", "en", "es", "de", "it", "pt", "ru", "zh", "ja", "hi", "ar", "bn", "id", "ur"]


def T(*v):
    assert len(v) == 14, v[0]
    return dict(zip(L, v))


K = {
 # ---- P6
 "hist.port6.0.dit": T("Regarde le facteur travailler en détail : `curl -v http://localhost:8042/`.", "Watch the postman work in detail: `curl -v http://localhost:8042/`.", "Mira al cartero trabajar en detalle: `curl -v http://localhost:8042/`.", "Schau dem Briefträger genau bei der Arbeit zu: `curl -v http://localhost:8042/`.", "Guarda il postino lavorare nei dettagli: `curl -v http://localhost:8042/`.", "Vê o carteiro a trabalhar em pormenor: `curl -v http://localhost:8042/`.", "Посмотри, как работает почтальон, во всех подробностях: `curl -v http://localhost:8042/`.", "仔细看邮差是怎么工作的：`curl -v http://localhost:8042/`。", "郵便屋さんの仕事をくわしく見てみよう：`curl -v http://localhost:8042/`。", "डाकिए का काम बारीकी से देखो: `curl -v http://localhost:8042/`।", "شاهد ساعي البريد يعمل بالتفصيل: `curl -v http://localhost:8042/`.", "ডাকপিয়নের কাজ খুঁটিয়ে দেখো: `curl -v http://localhost:8042/`।", "Lihat tukang pos bekerja secara rinci: `curl -v http://localhost:8042/`.", "ڈاکیے کا کام تفصیل سے دیکھو: `curl -v http://localhost:8042/`۔"),
 "hist.port6.0.bravo": T("Les lignes « * » parlent de l'adresse et du transport, les « > » sont ta lettre, les « < » la réponse. Plusieurs enveloppes !", "The \"*\" lines talk about the address and transport, the \">\" lines are your letter, the \"<\" lines the reply. Several envelopes!", "Las líneas «*» hablan de la dirección y el transporte, las «>» son tu carta, las «<» la respuesta. ¡Varios sobres!", "Die „*“-Zeilen sprechen von Adresse und Transport, die „>“ sind dein Brief, die „<“ die Antwort. Mehrere Umschläge!", "Le righe «*» parlano dell'indirizzo e del trasporto, le «>» sono la tua lettera, le «<» la risposta. Più buste!", "As linhas «*» falam do endereço e do transporte, as «>» são a tua carta, as «<» a resposta. Vários envelopes!", "Строки «*» говорят об адресе и транспорте, «>» — твоё письмо, «<» — ответ. Несколько конвертов!", "「*」开头的行讲地址和传输，「>」是你的信，「<」是回信。好几层信封！", "「*」の行はアドレスと運び方、「>」はきみの手紙、「<」は返事。封筒がいくつも重なっているね！", "«*» वाली पंक्तियाँ पते और परिवहन की बात करती हैं, «>» तुम्हारी चिट्ठी है, «<» जवाब। कई लिफ़ाफ़े!", "أسطر «*» تتحدث عن العنوان والنقل، وأسطر «>» رسالتك، و«<» الرد. عدة مظاريف!", "«*» লাইনগুলো ঠিকানা আর পরিবহনের কথা বলে, «>» তোমার চিঠি, «<» উত্তর। অনেকগুলো খাম!", "Baris \"*\" membahas alamat dan pengiriman, baris \">\" adalah suratmu, baris \"<\" jawabannya. Beberapa amplop!", "«*» والی سطریں پتے اور ترسیل کی بات کرتی ہیں، «>» تمہارا خط ہے، «<» جواب۔ کئی لفافے!"),
 "hist.port6.0.adulte": T("-v (verbeux) montre la connexion TCP (adresse et port), la requête HTTP envoyée (>) et les en-têtes reçus (<).", "-v (verbose) shows the TCP connection (address and port), the HTTP request sent (>) and the headers received (<).", "-v (detallado) muestra la conexión TCP (dirección y puerto), la petición HTTP enviada (>) y las cabeceras recibidas (<).", "-v (ausführlich) zeigt die TCP-Verbindung (Adresse und Port), die gesendete HTTP-Anfrage (>) und die empfangenen Kopfzeilen (<).", "-v (verboso) mostra la connessione TCP (indirizzo e porta), la richiesta HTTP inviata (>) e le intestazioni ricevute (<).", "-v (detalhado) mostra a ligação TCP (endereço e porta), o pedido HTTP enviado (>) e os cabeçalhos recebidos (<).", "-v (подробно) показывает TCP-соединение (адрес и порт), отправленный HTTP-запрос (>) и полученные заголовки (<).", "-v（详细）显示 TCP 连接（地址和端口）、发出的 HTTP 请求（>）和收到的头部（<）。", "-v（くわしく）は、TCP 接続（アドレスとポート）、送った HTTP リクエスト（>）、受け取ったヘッダー（<）を見せる。", "-v (विस्तृत) TCP कनेक्शन (पता और पोर्ट), भेजा गया HTTP अनुरोध (>) और मिले हेडर (<) दिखाता है।", "يعرض -v (مفصّل) اتصال TCP (العنوان والمنفذ)، وطلب HTTP المُرسل (>)، والترويسات المستلمة (<).", "-v (বিস্তারিত) TCP সংযোগ (ঠিকানা ও পোর্ট), পাঠানো HTTP অনুরোধ (>) আর পাওয়া হেডার (<) দেখায়।", "-v (rinci) menampilkan koneksi TCP (alamat dan port), permintaan HTTP yang dikirim (>) dan kepala yang diterima (<).", "-v (تفصیلی) TCP کنکشن (پتہ اور پورٹ)، بھیجی گئی HTTP درخواست (>) اور ملے ہیڈر (<) دکھاتا ہے۔"),
 "hist.port6.1.dit": T("Ouvre les enveloppes une par une : `port couches`.", "Open the envelopes one by one: `port couches`.", "Abre los sobres uno a uno: `port couches`.", "Öffne die Umschläge einen nach dem anderen: `port couches`.", "Apri le buste una per una: `port couches`.", "Abre os envelopes um a um: `port couches`.", "Открой конверты по одному: `port couches`.", "一层一层打开信封：`port couches`。", "封筒をひとつずつ開けよう：`port couches`。", "लिफ़ाफ़े एक-एक करके खोलो: `port couches`।", "افتح المظاريف واحدًا تلو الآخر: `port couches`.", "খামগুলো একটা একটা করে খোলো: `port couches`।", "Buka amplopnya satu per satu: `port couches`.", "لفافے ایک ایک کر کے کھولو: `port couches`۔"),
 "hist.port6.1.bravo": T("La lettre (application) dans l'enveloppe (transport), dans le colis (réseau), dans le camion (liaison).", "The letter (application) inside the envelope (transport), inside the parcel (network), inside the truck (link).", "La carta (aplicación) en el sobre (transporte), en el paquete (red), en el camión (enlace).", "Der Brief (Anwendung) im Umschlag (Transport), im Paket (Netzwerk), im Lastwagen (Verbindung).", "La lettera (applicazione) nella busta (trasporto), nel pacco (rete), nel camion (collegamento).", "A carta (aplicação) no envelope (transporte), na encomenda (rede), no camião (ligação).", "Письмо (приложение) в конверте (транспорт), в посылке (сеть), в грузовике (канал).", "信（应用层）在信封（传输层）里，信封在包裹（网络层）里，包裹在卡车（链路层）里。", "手紙（アプリケーション）が封筒（トランスポート）に、封筒が小包（ネットワーク）に、小包がトラック（リンク）に入っている。", "चिट्ठी (एप्लिकेशन) लिफ़ाफ़े (ट्रांसपोर्ट) में, लिफ़ाफ़ा पार्सल (नेटवर्क) में, पार्सल ट्रक (लिंक) में।", "الرسالة (التطبيق) في المظروف (النقل)، في الطرد (الشبكة)، في الشاحنة (الوصلة).", "চিঠি (অ্যাপ্লিকেশন) খামে (ট্রান্সপোর্ট), খাম পার্সেলে (নেটওয়ার্ক), পার্সেল ট্রাকে (লিংক)।", "Surat (aplikasi) di dalam amplop (transport), di dalam paket (jaringan), di dalam truk (tautan).", "خط (ایپلیکیشن) لفافے (ٹرانسپورٹ) میں، لفافہ پارسل (نیٹ ورک) میں، پارسل ٹرک (لنک) میں۔"),
 "hist.port6.1.adulte": T("Le modèle de l'Internet a 4 couches (RFC 1122) ; le modèle OSI en compte 7. Chaque couche ajoute son en-tête autour des données de la couche du dessus.", "The Internet model has 4 layers (RFC 1122); the OSI model has 7. Each layer adds its header around the data of the layer above.", "El modelo de Internet tiene 4 capas (RFC 1122); el modelo OSI tiene 7. Cada capa añade su cabecera alrededor de los datos de la capa superior.", "Das Internetmodell hat 4 Schichten (RFC 1122), das OSI-Modell 7. Jede Schicht legt ihren Kopf um die Daten der Schicht darüber.", "Il modello di Internet ha 4 livelli (RFC 1122); il modello OSI ne ha 7. Ogni livello aggiunge la sua intestazione attorno ai dati del livello superiore.", "O modelo da Internet tem 4 camadas (RFC 1122); o modelo OSI tem 7. Cada camada junta o seu cabeçalho à volta dos dados da camada de cima.", "В модели Интернета 4 уровня (RFC 1122), в модели OSI — 7. Каждый уровень добавляет свой заголовок вокруг данных уровня выше.", "互联网模型有 4 层（RFC 1122），OSI 模型有 7 层。每一层都在上一层的数据外面加上自己的头部。", "インターネットのモデルは 4 層（RFC 1122）、OSI モデルは 7 層。各層は上の層のデータのまわりに自分のヘッダーをつける。", "इंटरनेट मॉडल में 4 परतें हैं (RFC 1122); OSI मॉडल में 7। हर परत ऊपर वाली परत के डेटा के चारों ओर अपना हेडर जोड़ती है।", "لنموذج الإنترنت 4 طبقات (RFC 1122)، ولنموذج OSI سبع. كل طبقة تضيف ترويستها حول بيانات الطبقة التي فوقها.", "ইন্টারনেট মডেলে ৪টি স্তর (RFC 1122); OSI মডেলে ৭টি। প্রতিটি স্তর ওপরের স্তরের ডেটার চারপাশে নিজের হেডার জোড়ে।", "Model Internet punya 4 lapisan (RFC 1122); model OSI punya 7. Setiap lapisan menambahkan kepalanya di sekeliling data lapisan di atasnya.", "انٹرنیٹ ماڈل کی 4 تہیں ہیں (RFC 1122)؛ OSI ماڈل کی 7۔ ہر تہہ اوپر والی تہہ کے ڈیٹا کے گرد اپنا ہیڈر لگاتی ہے۔"),
 "hist.port6.2.dit": T("Écris les 4 couches dans l'ordre, de la lettre au camion : `echo \"application transport reseau liaison\" > couches.txt`.", "Write the 4 layers in order, from the letter to the truck: `echo \"application transport reseau liaison\" > couches.txt`.", "Escribe las 4 capas en orden, de la carta al camión: `echo \"application transport reseau liaison\" > couches.txt`.", "Schreib die 4 Schichten der Reihe nach, vom Brief bis zum Lastwagen: `echo \"application transport reseau liaison\" > couches.txt`.", "Scrivi i 4 livelli in ordine, dalla lettera al camion: `echo \"application transport reseau liaison\" > couches.txt`.", "Escreve as 4 camadas por ordem, da carta ao camião: `echo \"application transport reseau liaison\" > couches.txt`.", "Запиши 4 уровня по порядку, от письма до грузовика: `echo \"application transport reseau liaison\" > couches.txt`.", "按顺序写下 4 层，从信到卡车：`echo \"application transport reseau liaison\" > couches.txt`。", "手紙からトラックまで、4 つの層を順番に書こう：`echo \"application transport reseau liaison\" > couches.txt`。", "चिट्ठी से ट्रक तक, 4 परतें क्रम से लिखो: `echo \"application transport reseau liaison\" > couches.txt`।", "اكتب الطبقات الأربع بالترتيب من الرسالة إلى الشاحنة: `echo \"application transport reseau liaison\" > couches.txt`.", "চিঠি থেকে ট্রাক পর্যন্ত ৪টি স্তর ক্রম অনুযায়ী লেখো: `echo \"application transport reseau liaison\" > couches.txt`।", "Tulis 4 lapisan secara berurutan, dari surat sampai truk: `echo \"application transport reseau liaison\" > couches.txt`.", "خط سے ٹرک تک 4 تہیں ترتیب سے لکھو: `echo \"application transport reseau liaison\" > couches.txt`۔"),
 "hist.port6.2.bravo": T("Dans le bon ordre ! À l'arrivée, on déballe dans l'autre sens : le camion d'abord, la lettre en dernier.", "In the right order! On arrival, you unpack the other way round: the truck first, the letter last.", "¡En el orden correcto! Al llegar se desempaqueta al revés: primero el camión, la carta al final.", "In der richtigen Reihenfolge! Bei der Ankunft packt man andersherum aus: zuerst der Lastwagen, zuletzt der Brief.", "Nell'ordine giusto! All'arrivo si scarta al contrario: prima il camion, la lettera per ultima.", "Pela ordem certa! À chegada desembrulha-se ao contrário: primeiro o camião, a carta no fim.", "Правильный порядок! По прибытии распаковывают наоборот: сначала грузовик, письмо последним.", "顺序正确！到达时要反过来拆：先卡车，最后才是信。", "正しい順番！届いたら逆にほどいていく。トラックが先、手紙が最後。", "सही क्रम! पहुँचने पर उल्टा खोलते हैं: पहले ट्रक, आख़िर में चिट्ठी।", "بالترتيب الصحيح! عند الوصول نفكّ بالعكس: الشاحنة أولًا والرسالة أخيرًا.", "ঠিক ক্রমে! পৌঁছে উল্টো দিকে খোলা হয়: আগে ট্রাক, শেষে চিঠি।", "Urutannya benar! Saat tiba, kita membongkar sebaliknya: truk dulu, surat terakhir.", "صحیح ترتیب! پہنچ کر الٹا کھولتے ہیں: پہلے ٹرک، آخر میں خط۔"),
 "hist.port6.2.adulte": T("Encapsulation à l'envoi (application → liaison), désencapsulation à la réception (liaison → application).", "Encapsulation when sending (application → link), decapsulation when receiving (link → application).", "Encapsulación al enviar (aplicación → enlace), desencapsulación al recibir (enlace → aplicación).", "Kapselung beim Senden (Anwendung → Verbindung), Entkapselung beim Empfangen (Verbindung → Anwendung).", "Incapsulamento all'invio (applicazione → collegamento), decapsulamento alla ricezione (collegamento → applicazione).", "Encapsulamento no envio (aplicação → ligação), desencapsulamento na receção (ligação → aplicação).", "Инкапсуляция при отправке (приложение → канал), декапсуляция при приёме (канал → приложение).", "发送时封装（应用层 → 链路层），接收时解封装（链路层 → 应用层）。", "送るときはカプセル化（アプリケーション → リンク）、受けるときは逆（リンク → アプリケーション）。", "भेजते समय एनकैप्सुलेशन (एप्लिकेशन → लिंक), पाते समय डीकैप्सुलेशन (लिंक → एप्लिकेशन)।", "تغليف عند الإرسال (التطبيق ← الوصلة)، وفكّ التغليف عند الاستلام (الوصلة ← التطبيق).", "পাঠানোর সময় এনক্যাপসুলেশন (অ্যাপ্লিকেশন → লিংক), পাওয়ার সময় ডিক্যাপসুলেশন (লিংক → অ্যাপ্লিকেশন)।", "Enkapsulasi saat mengirim (aplikasi → tautan), dekapsulasi saat menerima (tautan → aplikasi).", "بھیجتے وقت انکیپسولیشن (ایپلیکیشن ← لنک)، وصول کرتے وقت ڈی کیپسولیشن (لنک ← ایپلیکیشن)۔"),

 # ---- P7
 "hist.port7.0.dit": T("Qui écoute dans ton ordinateur ? Les portes ouvertes : `ss -tln`.", "Who is listening inside your computer? The open doors: `ss -tln`.", "¿Quién escucha en tu ordenador? Las puertas abiertas: `ss -tln`.", "Wer lauscht in deinem Computer? Die offenen Türen: `ss -tln`.", "Chi ascolta nel tuo computer? Le porte aperte: `ss -tln`.", "Quem escuta no teu computador? As portas abertas: `ss -tln`.", "Кто слушает в твоём компьютере? Открытые двери: `ss -tln`.", "你的电脑里谁在听？打开的门：`ss -tln`。", "コンピューターの中でだれが待っている？開いているドア：`ss -tln`。", "तुम्हारे कंप्यूटर में कौन सुन रहा है? खुले दरवाज़े: `ss -tln`।", "من يستمع داخل حاسوبك؟ الأبواب المفتوحة: `ss -tln`.", "তোমার কম্পিউটারে কে শুনছে? খোলা দরজাগুলো: `ss -tln`।", "Siapa yang mendengarkan di komputermu? Pintu-pintu terbuka: `ss -tln`.", "تمہارے کمپیوٹر میں کون سن رہا ہے؟ کھلے دروازے: `ss -tln`۔"),
 "hist.port7.0.bravo": T("Chaque ligne LISTEN est une porte ouverte qui attend des visiteurs : une adresse, deux-points, un numéro de porte.", "Each LISTEN line is an open door waiting for visitors: an address, a colon, a door number.", "Cada línea LISTEN es una puerta abierta que espera visitas: una dirección, dos puntos, un número de puerta.", "Jede LISTEN-Zeile ist eine offene Tür, die auf Besuch wartet: eine Adresse, ein Doppelpunkt, eine Türnummer.", "Ogni riga LISTEN è una porta aperta che aspetta visitatori: un indirizzo, due punti, un numero di porta.", "Cada linha LISTEN é uma porta aberta à espera de visitas: um endereço, dois pontos, um número de porta.", "Каждая строка LISTEN — открытая дверь, которая ждёт гостей: адрес, двоеточие, номер двери.", "每一行 LISTEN 都是一扇等客人的门：一个地址，一个冒号，一个门牌号。", "LISTEN の行はどれも、お客さんを待つ開いたドア。アドレス、コロン、ドアの番号。", "हर LISTEN पंक्ति मेहमानों का इंतज़ार करता खुला दरवाज़ा है: एक पता, कोलन, एक दरवाज़ा-नंबर।", "كل سطر LISTEN باب مفتوح ينتظر الزوار: عنوان، ثم نقطتان، ثم رقم الباب.", "প্রতিটি LISTEN লাইন অতিথির অপেক্ষায় একটা খোলা দরজা: একটা ঠিকানা, কোলন, দরজার নম্বর।", "Setiap baris LISTEN adalah pintu terbuka yang menunggu tamu: alamat, titik dua, nomor pintu.", "ہر LISTEN سطر مہمانوں کا انتظار کرتا کھلا دروازہ ہے: ایک پتہ، کولن، دروازے کا نمبر۔"),
 "hist.port7.0.adulte": T("`ss -tln` liste les sockets TCP (-t) en écoute (-l) sans traduire les numéros (-n). 127.0.0.1:8042 n'accepte que des connexions locales ; 0.0.0.0 accepte tout le réseau.", "`ss -tln` lists TCP sockets (-t) that are listening (-l) without translating numbers (-n). 127.0.0.1:8042 only accepts local connections; 0.0.0.0 accepts the whole network.", "`ss -tln` lista los sockets TCP (-t) a la escucha (-l) sin traducir números (-n). 127.0.0.1:8042 solo acepta conexiones locales; 0.0.0.0 acepta toda la red.", "`ss -tln` listet lauschende (-l) TCP-Sockets (-t), ohne Nummern zu übersetzen (-n). 127.0.0.1:8042 nimmt nur lokale Verbindungen an; 0.0.0.0 das ganze Netz.", "`ss -tln` elenca i socket TCP (-t) in ascolto (-l) senza tradurre i numeri (-n). 127.0.0.1:8042 accetta solo connessioni locali; 0.0.0.0 accetta tutta la rete.", "`ss -tln` lista os sockets TCP (-t) à escuta (-l) sem traduzir números (-n). 127.0.0.1:8042 só aceita ligações locais; 0.0.0.0 aceita toda a rede.", "`ss -tln` показывает слушающие (-l) TCP-сокеты (-t), не переводя номера (-n). 127.0.0.1:8042 принимает только локальные соединения; 0.0.0.0 — всю сеть.", "`ss -tln` 列出正在监听（-l）的 TCP 套接字（-t），数字不做转换（-n）。127.0.0.1:8042 只接受本机连接；0.0.0.0 接受整个网络。", "`ss -tln` は待ち受け中（-l）の TCP ソケット（-t）を、番号を変換せず（-n）表示する。127.0.0.1:8042 はローカル接続だけ、0.0.0.0 はネットワーク全体を受け入れる。", "`ss -tln` सुन रहे (-l) TCP सॉकेट (-t) बिना संख्या बदले (-n) दिखाता है। 127.0.0.1:8042 सिर्फ़ स्थानीय कनेक्शन लेता है; 0.0.0.0 पूरे नेटवर्क को।", "يعرض `ss -tln` مقابس TCP ‏(-t) المستمعة (-l) دون ترجمة الأرقام (-n). يقبل 127.0.0.1:8042 الاتصالات المحلية فقط؛ و 0.0.0.0 يقبل الشبكة كلها.", "`ss -tln` শোনার অবস্থায় (-l) থাকা TCP সকেট (-t) সংখ্যা না বদলে (-n) দেখায়। 127.0.0.1:8042 শুধু স্থানীয় সংযোগ নেয়; 0.0.0.0 পুরো নেটওয়ার্ক।", "`ss -tln` menampilkan soket TCP (-t) yang mendengarkan (-l) tanpa menerjemahkan angka (-n). 127.0.0.1:8042 hanya menerima koneksi lokal; 0.0.0.0 menerima seluruh jaringan.", "`ss -tln` سن رہے (-l) TCP ساکٹ (-t) نمبر بدلے بغیر (-n) دکھاتا ہے۔ 127.0.0.1:8042 صرف مقامی کنکشن لیتا ہے؛ 0.0.0.0 پورا نیٹ ورک۔"),
 "hist.port7.1.dit": T("Trouve la porte du phare avec un tuyau : `ss -tln | grep 8042`.", "Find the lighthouse's door with a pipe: `ss -tln | grep 8042`.", "Encuentra la puerta del faro con una tubería: `ss -tln | grep 8042`.", "Finde die Tür des Leuchtturms mit einer Pipe: `ss -tln | grep 8042`.", "Trova la porta del faro con un tubo: `ss -tln | grep 8042`.", "Encontra a porta do farol com um cano: `ss -tln | grep 8042`.", "Найди дверь маяка с помощью трубы: `ss -tln | grep 8042`.", "用管道找出灯塔的门：`ss -tln | grep 8042`。", "パイプで灯台のドアを見つけよう：`ss -tln | grep 8042`。", "पाइप से प्रकाशस्तंभ का दरवाज़ा ढूँढो: `ss -tln | grep 8042`।", "جد باب المنارة بأنبوب: `ss -tln | grep 8042`.", "পাইপ দিয়ে বাতিঘরের দরজা খুঁজে বের করো: `ss -tln | grep 8042`।", "Temukan pintu mercusuar dengan pipa: `ss -tln | grep 8042`.", "پائپ سے لائٹ ہاؤس کا دروازہ ڈھونڈو: `ss -tln | grep 8042`۔"),
 "hist.port7.1.bravo": T("127.0.0.1:8042 : le quai 127.0.0.1, la porte 8042. Une adresse IP et un port, c'est l'adresse complète d'un service.", "127.0.0.1:8042: dock 127.0.0.1, door 8042. An IP address plus a port is the full address of a service.", "127.0.0.1:8042: el muelle 127.0.0.1, la puerta 8042. Una dirección IP y un puerto son la dirección completa de un servicio.", "127.0.0.1:8042: Kai 127.0.0.1, Tür 8042. IP-Adresse plus Port ist die vollständige Adresse eines Dienstes.", "127.0.0.1:8042: la banchina 127.0.0.1, la porta 8042. Indirizzo IP più porta è l'indirizzo completo di un servizio.", "127.0.0.1:8042: o cais 127.0.0.1, a porta 8042. Um endereço IP mais uma porta é o endereço completo de um serviço.", "127.0.0.1:8042: причал 127.0.0.1, дверь 8042. IP-адрес плюс порт — полный адрес службы.", "127.0.0.1:8042：码头 127.0.0.1，门 8042。IP 地址加端口，就是一个服务的完整地址。", "127.0.0.1:8042 は、波止場 127.0.0.1 のドア 8042。IP アドレスとポートで、サービスの完全な住所になる。", "127.0.0.1:8042: घाट 127.0.0.1, दरवाज़ा 8042। IP पता और पोर्ट मिलकर किसी सेवा का पूरा पता हैं।", "127.0.0.1:8042: الرصيف 127.0.0.1 والباب 8042. عنوان IP مع المنفذ هو العنوان الكامل لخدمة.", "127.0.0.1:8042: ঘাট 127.0.0.1, দরজা 8042। IP ঠিকানা আর পোর্ট মিলে একটা সেবার পুরো ঠিকানা।", "127.0.0.1:8042: dermaga 127.0.0.1, pintu 8042. Alamat IP ditambah port adalah alamat lengkap sebuah layanan.", "127.0.0.1:8042: گودی 127.0.0.1، دروازہ 8042۔ IP پتہ اور پورٹ مل کر کسی سروس کا پورا پتہ ہیں۔"),
 "hist.port7.1.adulte": T("L'adresse IP désigne la machine, le port (0 à 65535) le programme qui écoute. Les ports sous 1024 sont réservés aux services du système.", "The IP address names the machine, the port (0 to 65535) the program listening. Ports below 1024 are reserved for system services.", "La dirección IP designa la máquina; el puerto (0 a 65535), el programa que escucha. Los puertos por debajo de 1024 están reservados al sistema.", "Die IP-Adresse bezeichnet die Maschine, der Port (0 bis 65535) das lauschende Programm. Ports unter 1024 sind Systemdiensten vorbehalten.", "L'indirizzo IP indica la macchina, la porta (da 0 a 65535) il programma in ascolto. Le porte sotto 1024 sono riservate ai servizi di sistema.", "O endereço IP designa a máquina, a porta (0 a 65535) o programa que escuta. As portas abaixo de 1024 são reservadas aos serviços do sistema.", "IP-адрес обозначает машину, порт (от 0 до 65535) — программу, которая слушает. Порты ниже 1024 зарезервированы для системных служб.", "IP 地址指明机器，端口（0 到 65535）指明正在监听的程序。1024 以下的端口留给系统服务。", "IP アドレスはマシンを、ポート（0〜65535）は待ち受けているプログラムを指す。1024 未満のポートはシステムのサービス用。", "IP पता मशीन बताता है, पोर्ट (0 से 65535) सुनने वाला प्रोग्राम। 1024 से नीचे के पोर्ट सिस्टम सेवाओं के लिए आरक्षित हैं।", "عنوان IP يحدد الآلة، والمنفذ (من 0 إلى 65535) يحدد البرنامج المستمع. المنافذ تحت 1024 محجوزة لخدمات النظام.", "IP ঠিকানা যন্ত্রকে বোঝায়, পোর্ট (০ থেকে ৬৫৫৩৫) যে প্রোগ্রাম শুনছে তাকে। ১০২৪-এর নিচের পোর্টগুলো সিস্টেম-সেবার জন্য সংরক্ষিত।", "Alamat IP menunjuk mesin, port (0 sampai 65535) menunjuk program yang mendengarkan. Port di bawah 1024 dicadangkan untuk layanan sistem.", "IP پتہ مشین بتاتا ہے، پورٹ (0 سے 65535) سننے والا پروگرام۔ 1024 سے نیچے کے پورٹ سسٹم سروسز کے لیے مخصوص ہیں۔"),
 "hist.port7.2.dit": T("Une machine peut avoir plusieurs adresses. Relève toutes celles du Terminaworld : `port carte`.", "A machine can have several addresses. Note down all the Terminaworld's: `port carte`.", "Una máquina puede tener varias direcciones. Apunta todas las del Terminaworld: `port carte`.", "Eine Maschine kann mehrere Adressen haben. Notiere alle der Terminaworld: `port carte`.", "Una macchina può avere più indirizzi. Annota tutti quelli del Terminaworld: `port carte`.", "Uma máquina pode ter vários endereços. Aponta todos os do Terminaworld: `port carte`.", "У машины может быть несколько адресов. Запиши все адреса Terminaworld: `port carte`.", "一台机器可以有好几个地址。把 Terminaworld 的都记下来：`port carte`。", "マシンはアドレスをいくつも持てる。Terminaworld のアドレスをぜんぶ書きとめよう：`port carte`。", "एक मशीन के कई पते हो सकते हैं। Terminaworld के सारे पते नोट करो: `port carte`।", "يمكن أن يكون لآلة عدة عناوين. دوّن كل عناوين Terminaworld: `port carte`.", "একটা যন্ত্রের অনেকগুলো ঠিকানা থাকতে পারে। Terminaworld-এর সবগুলো লিখে রাখো: `port carte`।", "Satu mesin bisa punya beberapa alamat. Catat semua alamat Terminaworld: `port carte`.", "ایک مشین کے کئی پتے ہو سکتے ہیں۔ Terminaworld کے سارے پتے لکھ لو: `port carte`۔"),
 "hist.port7.2.bravo": T("11 machines, 11 adresses, et les phares qui les relient. Ta carte est notée dans le carnet de bord.", "11 machines, 11 addresses, and the lighthouses linking them. Your map is written in the logbook.", "11 máquinas, 11 direcciones y los faros que las unen. Tu mapa queda anotado en el cuaderno de bitácora.", "11 Maschinen, 11 Adressen und die Leuchttürme, die sie verbinden. Deine Karte steht im Logbuch.", "11 macchine, 11 indirizzi e i fari che le collegano. La tua mappa è annotata nel diario di bordo.", "11 máquinas, 11 endereços e os faróis que as ligam. O teu mapa fica no diário de bordo.", "11 машин, 11 адресов и маяки, которые их соединяют. Твоя карта записана в бортовом журнале.", "11 台机器、11 个地址，还有连接它们的灯塔。你的地图记在航海日志里了。", "マシン 11 台、アドレス 11 個、そしてそれをつなぐ灯台。きみの地図は航海日誌に書いたよ。", "11 मशीनें, 11 पते, और उन्हें जोड़ने वाले प्रकाशस्तंभ। तुम्हारा नक्शा लॉगबुक में लिखा गया।", "11 آلة، و11 عنوانًا، والمنارات التي تربطها. خريطتك مدوّنة في دفتر السفينة.", "১১টি যন্ত্র, ১১টি ঠিকানা, আর তাদের জোড়া বাতিঘর। তোমার মানচিত্র লগবইয়ে লেখা হলো।", "11 mesin, 11 alamat, dan mercusuar yang menghubungkannya. Petamu tercatat di buku catatan.", "11 مشینیں، 11 پتے، اور انہیں جوڑنے والے لائٹ ہاؤس۔ تمہارا نقشہ لاگ بک میں لکھا گیا۔"),
 "hist.port7.2.adulte": T("Toutes ces adresses sont dans 127.0.0.0/8 : sous Linux, ta machine répond sur chacune d'elles. Une vraie machine peut aussi avoir plusieurs cartes et plusieurs adresses (IPv4 et IPv6).", "All these addresses are in 127.0.0.0/8: on Linux, your machine answers on each of them. A real machine can also have several cards and several addresses (IPv4 and IPv6).", "Todas estas direcciones están en 127.0.0.0/8: en Linux, tu máquina responde en cada una. Una máquina real también puede tener varias tarjetas y varias direcciones (IPv4 e IPv6).", "Alle diese Adressen liegen in 127.0.0.0/8: Unter Linux antwortet deine Maschine auf jeder. Eine echte Maschine kann auch mehrere Karten und Adressen haben (IPv4 und IPv6).", "Tutti questi indirizzi sono in 127.0.0.0/8: su Linux la tua macchina risponde su ciascuno. Una macchina reale può avere anche più schede e più indirizzi (IPv4 e IPv6).", "Todos estes endereços estão em 127.0.0.0/8: no Linux, a tua máquina responde em cada um. Uma máquina real também pode ter várias placas e vários endereços (IPv4 e IPv6).", "Все эти адреса входят в 127.0.0.0/8: в Linux твоя машина отвечает на каждом. Настоящая машина тоже может иметь несколько карт и адресов (IPv4 и IPv6).", "这些地址都在 127.0.0.0/8 里：在 Linux 上，你的机器在每个地址上都会回应。真实的机器也可以有好几块网卡、好几个地址（IPv4 和 IPv6）。", "これらのアドレスはすべて 127.0.0.0/8 の中。Linux ならきみのマシンはどれにも応答する。本物のマシンもカードやアドレス（IPv4 と IPv6）を複数持てる。", "ये सारे पते 127.0.0.0/8 में हैं: Linux पर तुम्हारी मशीन हर एक पर जवाब देती है। असली मशीन के भी कई कार्ड और कई पते (IPv4 और IPv6) हो सकते हैं।", "كل هذه العناوين ضمن 127.0.0.0/8: في Linux تجيب آلتك على كل واحد منها. ويمكن لآلة حقيقية أيضًا أن تملك عدة بطاقات وعناوين (IPv4 و IPv6).", "এই সব ঠিকানা 127.0.0.0/8-এর মধ্যে: Linux-এ তোমার যন্ত্র প্রতিটিতে উত্তর দেয়। আসল যন্ত্রেরও অনেক কার্ড ও ঠিকানা (IPv4 ও IPv6) থাকতে পারে।", "Semua alamat ini ada di 127.0.0.0/8: di Linux, mesinmu menjawab di masing-masing. Mesin sungguhan juga bisa punya beberapa kartu dan alamat (IPv4 dan IPv6).", "یہ سارے پتے 127.0.0.0/8 میں ہیں: Linux پر تمہاری مشین ہر ایک پر جواب دیتی ہے۔ اصلی مشین کے بھی کئی کارڈ اور کئی پتے (IPv4 اور IPv6) ہو سکتے ہیں۔"),

 # ---- P8
 "hist.port8.0.dit": T("Les lettres recommandées, ce sont les connexions TCP : `ss -t`.", "Registered letters are TCP connections: `ss -t`.", "Las cartas certificadas son las conexiones TCP: `ss -t`.", "Einschreiben sind TCP-Verbindungen: `ss -t`.", "Le raccomandate sono le connessioni TCP: `ss -t`.", "As cartas registadas são as ligações TCP: `ss -t`.", "Заказные письма — это TCP-соединения: `ss -t`.", "挂号信就是 TCP 连接：`ss -t`。", "書留は TCP 接続のこと：`ss -t`。", "रजिस्टर्ड चिट्ठियाँ TCP कनेक्शन हैं: `ss -t`।", "الرسائل المسجّلة هي اتصالات TCP: `ss -t`.", "রেজিস্ট্রি চিঠি মানে TCP সংযোগ: `ss -t`।", "Surat tercatat adalah koneksi TCP: `ss -t`.", "رجسٹرڈ خط TCP کنکشن ہیں: `ss -t`۔"),
 "hist.port8.0.bravo": T("TCP ouvre une connexion, numérote les paquets et attend un accusé de réception pour chacun.", "TCP opens a connection, numbers the packets and waits for an acknowledgement for each one.", "TCP abre una conexión, numera los paquetes y espera un acuse de recibo de cada uno.", "TCP baut eine Verbindung auf, nummeriert die Pakete und wartet für jedes auf eine Empfangsbestätigung.", "TCP apre una connessione, numera i pacchetti e aspetta una ricevuta per ciascuno.", "O TCP abre uma ligação, numera os pacotes e espera um aviso de receção de cada um.", "TCP открывает соединение, нумерует пакеты и ждёт подтверждения для каждого.", "TCP 先建立连接，给数据包编号，并等待每个包的确认回执。", "TCP は接続を開き、パケットに番号をつけ、ひとつずつ受け取りの返事を待つ。", "TCP कनेक्शन खोलता है, पैकेटों पर नंबर डालता है और हर एक की पावती का इंतज़ार करता है।", "يفتح TCP اتصالًا، ويرقّم الحزم، وينتظر إشعار استلام لكل واحدة.", "TCP সংযোগ খোলে, প্যাকেটে নম্বর দেয় আর প্রতিটির প্রাপ্তিস্বীকারের অপেক্ষা করে।", "TCP membuka koneksi, memberi nomor pada paket, dan menunggu tanda terima untuk masing-masing.", "TCP کنکشن کھولتا ہے، پیکٹوں پر نمبر لگاتا ہے اور ہر ایک کی رسید کا انتظار کرتا ہے۔"),
 "hist.port8.0.adulte": T("`ss -t` liste les connexions TCP établies. TCP garantit l'ordre et la livraison (renvoi des segments perdus) : c'est le transport du Web, de ssh, des courriels.", "`ss -t` lists established TCP connections. TCP guarantees order and delivery (lost segments are resent): it carries the Web, ssh and e-mail.", "`ss -t` lista las conexiones TCP establecidas. TCP garantiza el orden y la entrega (reenvía los segmentos perdidos): transporta la web, ssh y el correo.", "`ss -t` listet bestehende TCP-Verbindungen. TCP garantiert Reihenfolge und Zustellung (verlorene Segmente werden neu gesendet): Es trägt das Web, ssh und E-Mails.", "`ss -t` elenca le connessioni TCP stabilite. TCP garantisce ordine e consegna (rinvia i segmenti persi): trasporta il Web, ssh e la posta.", "`ss -t` lista as ligações TCP estabelecidas. O TCP garante a ordem e a entrega (reenvia os segmentos perdidos): transporta a Web, o ssh e o correio.", "`ss -t` показывает установленные TCP-соединения. TCP гарантирует порядок и доставку (повторно шлёт потерянные сегменты): на нём работают веб, ssh и почта.", "`ss -t` 列出已建立的 TCP 连接。TCP 保证顺序和送达（重发丢失的分段）：网页、ssh 和电子邮件都用它。", "`ss -t` は確立した TCP 接続を表示する。TCP は順番と配達を保証する（なくした部分は送り直す）。ウェブ、ssh、メールを運ぶ。", "`ss -t` स्थापित TCP कनेक्शन दिखाता है। TCP क्रम और पहुँच की गारंटी देता है (खोए हिस्से दोबारा भेजता है): वेब, ssh और ईमेल इसी से चलते हैं।", "يعرض `ss -t` اتصالات TCP القائمة. يضمن TCP الترتيب والتسليم (يعيد إرسال المقاطع الضائعة): عليه يعمل الويب و ssh والبريد.", "`ss -t` প্রতিষ্ঠিত TCP সংযোগ দেখায়। TCP ক্রম আর পৌঁছানোর নিশ্চয়তা দেয় (হারানো অংশ আবার পাঠায়): ওয়েব, ssh আর ইমেল এতেই চলে।", "`ss -t` menampilkan koneksi TCP yang terjalin. TCP menjamin urutan dan pengiriman (segmen yang hilang dikirim ulang): web, ssh, dan surel memakainya.", "`ss -t` قائم TCP کنکشن دکھاتا ہے۔ TCP ترتیب اور ترسیل کی ضمانت دیتا ہے (کھوئے حصے دوبارہ بھیجتا ہے): ویب، ssh اور ای میل اسی پر چلتے ہیں۔"),
 "hist.port8.1.dit": T("Les cartes postales, c'est UDP : `ss -u`.", "Postcards are UDP: `ss -u`.", "Las postales son UDP: `ss -u`.", "Postkarten sind UDP: `ss -u`.", "Le cartoline sono UDP: `ss -u`.", "Os postais são UDP: `ss -u`.", "Открытки — это UDP: `ss -u`.", "明信片就是 UDP：`ss -u`。", "ハガキは UDP：`ss -u`。", "पोस्टकार्ड UDP हैं: `ss -u`।", "البطاقات البريدية هي UDP: `ss -u`.", "পোস্টকার্ড মানে UDP: `ss -u`।", "Kartu pos adalah UDP: `ss -u`.", "پوسٹ کارڈ UDP ہیں: `ss -u`۔"),
 "hist.port8.1.bravo": T("UDP envoie sans connexion et sans accusé : rapide, mais rien n'est garanti.", "UDP sends without a connection and without acknowledgements: fast, but nothing is guaranteed.", "UDP envía sin conexión y sin acuse: rápido, pero nada está garantizado.", "UDP sendet ohne Verbindung und ohne Bestätigung: schnell, aber nichts ist garantiert.", "UDP invia senza connessione e senza ricevuta: veloce, ma nulla è garantito.", "O UDP envia sem ligação e sem aviso de receção: rápido, mas nada é garantido.", "UDP отправляет без соединения и без подтверждений: быстро, но ничего не гарантировано.", "UDP 不建立连接也不要回执：很快，但什么都不保证。", "UDP は接続も返事もなしで送る。速いけど、何も保証されない。", "UDP बिना कनेक्शन और बिना पावती भेजता है: तेज़, पर कुछ भी पक्का नहीं।", "يرسل UDP دون اتصال ودون إشعار: سريع، لكن لا شيء مضمون.", "UDP সংযোগ ছাড়া, প্রাপ্তিস্বীকার ছাড়া পাঠায়: দ্রুত, কিন্তু কিছুই নিশ্চিত নয়।", "UDP mengirim tanpa koneksi dan tanpa tanda terima: cepat, tapi tidak ada yang dijamin.", "UDP بغیر کنکشن اور بغیر رسید بھیجتا ہے: تیز، مگر کچھ بھی یقینی نہیں۔"),
 "hist.port8.1.adulte": T("`ss -u` liste les sockets UDP. UDP sert quand la vitesse compte plus qu'une perte : DNS, jeux en ligne, voix et vidéo en direct.", "`ss -u` lists UDP sockets. UDP is used when speed matters more than a loss: DNS, online games, live voice and video.", "`ss -u` lista los sockets UDP. UDP se usa cuando la velocidad importa más que una pérdida: DNS, juegos en línea, voz y vídeo en directo.", "`ss -u` listet UDP-Sockets. UDP nimmt man, wenn Tempo wichtiger ist als ein Verlust: DNS, Onlinespiele, Sprache und Video live.", "`ss -u` elenca i socket UDP. UDP si usa quando la velocità conta più di una perdita: DNS, giochi online, voce e video in diretta.", "`ss -u` lista os sockets UDP. O UDP usa-se quando a velocidade conta mais do que uma perda: DNS, jogos online, voz e vídeo em direto.", "`ss -u` показывает UDP-сокеты. UDP выбирают, когда скорость важнее потерь: DNS, онлайн-игры, голос и видео в прямом эфире.", "`ss -u` 列出 UDP 套接字。当速度比丢包更重要时用 UDP：DNS、网络游戏、实时语音和视频。", "`ss -u` は UDP ソケットを表示する。UDP は、なくなることより速さが大事なときに使う：DNS、オンラインゲーム、生の音声や映像。", "`ss -u` UDP सॉकेट दिखाता है। UDP तब काम आता है जब खोने से ज़्यादा गति ज़रूरी हो: DNS, ऑनलाइन खेल, लाइव आवाज़ और वीडियो।", "يعرض `ss -u` مقابس UDP. يُستعمل UDP حين تهمّ السرعة أكثر من الخسارة: DNS، والألعاب عبر الشبكة، والصوت والفيديو المباشر.", "`ss -u` UDP সকেট দেখায়। হারানোর চেয়ে গতি যখন বেশি জরুরি তখন UDP: DNS, অনলাইন খেলা, সরাসরি কণ্ঠ ও ভিডিও।", "`ss -u` menampilkan soket UDP. UDP dipakai saat kecepatan lebih penting daripada kehilangan: DNS, gim daring, suara dan video langsung.", "`ss -u` UDP ساکٹ دکھاتا ہے۔ UDP تب استعمال ہوتا ہے جب نقصان سے زیادہ رفتار اہم ہو: DNS، آن لائن کھیل، براہ راست آواز اور ویڈیو۔"),
 "hist.port8.2.dit": T("Lance la course entre le messager TCP et le messager UDP : `port course`.", "Start the race between the TCP messenger and the UDP messenger: `port course`.", "Empieza la carrera entre el mensajero TCP y el mensajero UDP: `port course`.", "Starte das Rennen zwischen dem TCP-Boten und dem UDP-Boten: `port course`.", "Lancia la gara tra il messaggero TCP e il messaggero UDP: `port course`.", "Começa a corrida entre o mensageiro TCP e o mensageiro UDP: `port course`.", "Запусти гонку между гонцом TCP и гонцом UDP: `port course`.", "让 TCP 信使和 UDP 信使赛跑：`port course`。", "TCP のメッセンジャーと UDP のメッセンジャーで競走だ：`port course`。", "TCP संदेशवाहक और UDP संदेशवाहक की दौड़ शुरू करो: `port course`।", "ابدأ السباق بين رسول TCP ورسول UDP: `port course`.", "TCP বার্তাবাহক আর UDP বার্তাবাহকের দৌড় শুরু করো: `port course`।", "Mulai lomba antara pengantar TCP dan pengantar UDP: `port course`.", "TCP قاصد اور UDP قاصد کی دوڑ شروع کرو: `port course`۔"),
 "hist.port8.2.bravo": T("TCP a tout livré dans l'ordre en renvoyant les paquets 2 et 5. UDP a filé plus vite, mais a perdu 2 paquets et en a mélangé 2.", "TCP delivered everything in order by resending packets 2 and 5. UDP was faster, but lost 2 packets and mixed up 2.", "TCP lo entregó todo en orden reenviando los paquetes 2 y 5. UDP fue más rápido, pero perdió 2 paquetes y desordenó 2.", "TCP hat alles der Reihe nach geliefert und die Pakete 2 und 5 neu gesendet. UDP war schneller, hat aber 2 Pakete verloren und 2 vertauscht.", "TCP ha consegnato tutto in ordine rinviando i pacchetti 2 e 5. UDP è stato più veloce, ma ha perso 2 pacchetti e ne ha scambiati 2.", "O TCP entregou tudo por ordem, reenviando os pacotes 2 e 5. O UDP foi mais rápido, mas perdeu 2 pacotes e trocou 2.", "TCP доставил всё по порядку, переслав пакеты 2 и 5. UDP был быстрее, но потерял 2 пакета и перепутал 2.", "TCP 重发了第 2 和第 5 个包，所有包都按顺序送到。UDP 跑得更快，可丢了 2 个包，还弄乱了 2 个。", "TCP は 2 番と 5 番を送り直して、ぜんぶ順番どおりに届けた。UDP は速かったけど、2 つなくして 2 つの順番がいれかわった。", "TCP ने पैकेट 2 और 5 दोबारा भेजकर सब कुछ क्रम से पहुँचाया। UDP तेज़ था, पर 2 पैकेट खो दिए और 2 आगे-पीछे हो गए।", "سلّم TCP كل شيء بالترتيب بإعادة إرسال الحزمتين 2 و5. كان UDP أسرع، لكنه أضاع حزمتين وخلط اثنتين.", "TCP ২ আর ৫ নম্বর প্যাকেট আবার পাঠিয়ে সব ক্রম মেনে পৌঁছে দিল। UDP দ্রুত ছিল, কিন্তু ২টি প্যাকেট হারাল আর ২টি উল্টোপাল্টা হলো।", "TCP mengantar semuanya berurutan dengan mengirim ulang paket 2 dan 5. UDP lebih cepat, tapi kehilangan 2 paket dan menukar 2.", "TCP نے پیکٹ 2 اور 5 دوبارہ بھیج کر سب کچھ ترتیب سے پہنچایا۔ UDP تیز تھا، مگر 2 پیکٹ کھو دیے اور 2 آگے پیچھے ہو گئے۔"),
 "hist.port8.2.adulte": T("Même réseau, mêmes pertes : TCP les corrige (retransmission, remise en ordre), UDP les laisse à l'application.", "Same network, same losses: TCP fixes them (retransmission, reordering), UDP leaves them to the application.", "Misma red, mismas pérdidas: TCP las corrige (retransmisión, reordenación), UDP se las deja a la aplicación.", "Gleiches Netz, gleiche Verluste: TCP behebt sie (Neuübertragung, Neuordnung), UDP überlässt sie der Anwendung.", "Stessa rete, stesse perdite: TCP le corregge (ritrasmissione, riordino), UDP le lascia all'applicazione.", "Mesma rede, mesmas perdas: o TCP corrige-as (retransmissão, reordenação), o UDP deixa-as para a aplicação.", "Та же сеть, те же потери: TCP их исправляет (повторная передача, упорядочивание), UDP оставляет приложению.", "同一个网络、同样的丢包：TCP 会纠正（重传、重新排序），UDP 把问题留给应用程序。", "同じネットワーク、同じ損失。TCP はそれを直し（再送、並べなおし）、UDP はアプリケーションにまかせる。", "वही नेटवर्क, वही नुकसान: TCP उन्हें ठीक करता है (दोबारा भेजना, क्रम बहाल करना), UDP उन्हें एप्लिकेशन पर छोड़ देता है।", "الشبكة نفسها والخسائر نفسها: يصلحها TCP (إعادة الإرسال وإعادة الترتيب)، ويتركها UDP للتطبيق.", "একই নেটওয়ার্ক, একই ক্ষতি: TCP সারায় (আবার পাঠানো, ক্রম ঠিক করা), UDP অ্যাপ্লিকেশনের ওপর ছেড়ে দেয়।", "Jaringan sama, kehilangan sama: TCP memperbaikinya (kirim ulang, urutkan ulang), UDP menyerahkannya ke aplikasi.", "وہی نیٹ ورک، وہی نقصان: TCP انہیں ٹھیک کرتا ہے (دوبارہ بھیجنا، ترتیب درست کرنا)، UDP انہیں ایپلیکیشن پر چھوڑ دیتا ہے۔"),

 # ---- P9
 "hist.port9.0.dit": T("Ton ordinateur a une carte des routes : `ip route`.", "Your computer has a map of routes: `ip route`.", "Tu ordenador tiene un mapa de rutas: `ip route`.", "Dein Computer hat eine Routenkarte: `ip route`.", "Il tuo computer ha una mappa delle strade: `ip route`.", "O teu computador tem um mapa de rotas: `ip route`.", "У твоего компьютера есть карта маршрутов: `ip route`.", "你的电脑有一张路线图：`ip route`。", "きみのコンピューターには道の地図がある：`ip route`。", "तुम्हारे कंप्यूटर के पास रास्तों का नक्शा है: `ip route`।", "لحاسوبك خريطة طرق: `ip route`.", "তোমার কম্পিউটারের কাছে পথের একটা মানচিত্র আছে: `ip route`।", "Komputermu punya peta rute: `ip route`.", "تمہارے کمپیوٹر کے پاس راستوں کا نقشہ ہے: `ip route`۔"),
 "hist.port9.0.bravo": T("La ligne default via… indique la passerelle : la porte par où partent tous les messagers qui vont loin.", "The default via… line shows the gateway: the door through which every far-travelling messenger leaves.", "La línea default via… indica la pasarela: la puerta por donde salen todos los mensajeros que van lejos.", "Die Zeile default via… zeigt das Gateway: die Tür, durch die alle Boten in die Ferne gehen.", "La riga default via… indica il gateway: la porta da cui partono tutti i messaggeri che vanno lontano.", "A linha default via… indica a porta de ligação: por onde saem todos os mensageiros que vão longe.", "Строка default via… показывает шлюз: дверь, через которую уходят все гонцы в дальний путь.", "default via… 这一行指出网关：所有要去远方的信使都从这扇门出发。", "default via… の行はゲートウェイ。遠くへ行くメッセンジャーはみんなこのドアから出ていく。", "default via… वाली पंक्ति गेटवे बताती है: वह दरवाज़ा जिससे दूर जाने वाले सारे संदेशवाहक निकलते हैं।", "سطر default via… يدل على البوابة: الباب الذي يخرج منه كل رسول يذهب بعيدًا.", "default via… লাইনটা গেটওয়ে দেখায়: দূরে যাওয়া সব বার্তাবাহক যে দরজা দিয়ে বেরোয়।", "Baris default via… menunjukkan gateway: pintu tempat semua pengantar yang pergi jauh keluar.", "default via… والی سطر گیٹ وے بتاتی ہے: وہ دروازہ جس سے دور جانے والے سارے قاصد نکلتے ہیں۔"),
 "hist.port9.0.adulte": T("`ip route` affiche la table de routage : pour chaque destination, l'interface et la passerelle à utiliser. La route par défaut sert pour tout le reste.", "`ip route` shows the routing table: for each destination, the interface and gateway to use. The default route covers everything else.", "`ip route` muestra la tabla de rutas: para cada destino, la interfaz y la pasarela que usar. La ruta por defecto sirve para todo lo demás.", "`ip route` zeigt die Routingtabelle: für jedes Ziel die Schnittstelle und das Gateway. Die Standardroute gilt für alles andere.", "`ip route` mostra la tabella di instradamento: per ogni destinazione, l'interfaccia e il gateway da usare. La rotta predefinita vale per tutto il resto.", "`ip route` mostra a tabela de encaminhamento: para cada destino, a interface e a porta de ligação a usar. A rota por omissão serve para o resto.", "`ip route` показывает таблицу маршрутизации: для каждого адресата — интерфейс и шлюз. Маршрут по умолчанию — для всего остального.", "`ip route` 显示路由表：每个目的地该走哪个接口、哪个网关。默认路由负责其余所有地方。", "`ip route` はルーティングテーブルを表示する。行き先ごとに使うインターフェースとゲートウェイ。デフォルトルートはそれ以外ぜんぶ。", "`ip route` रूटिंग टेबल दिखाता है: हर मंज़िल के लिए कौन-सा इंटरफ़ेस और गेटवे। डिफ़ॉल्ट रूट बाक़ी सबके लिए है।", "يعرض `ip route` جدول التوجيه: لكل وجهة الواجهة والبوابة المستعملتان. والمسار الافتراضي لكل ما تبقى.", "`ip route` রাউটিং টেবিল দেখায়: প্রতিটি গন্তব্যের জন্য কোন ইন্টারফেস ও গেটওয়ে। ডিফল্ট রুট বাকি সবকিছুর জন্য।", "`ip route` menampilkan tabel perutean: untuk setiap tujuan, antarmuka dan gateway yang dipakai. Rute bawaan untuk sisanya.", "`ip route` روٹنگ ٹیبل دکھاتا ہے: ہر منزل کے لیے کون سا انٹرفیس اور گیٹ وے۔ ڈیفالٹ روٹ باقی سب کے لیے ہے۔"),
 "hist.port9.1.dit": T("Suis un messager phare par phare jusqu'à ton propre camp : `tracepath -n 127.0.0.1`.", "Follow a messenger lighthouse by lighthouse to your own camp: `tracepath -n 127.0.0.1`.", "Sigue a un mensajero faro a faro hasta tu propio campamento: `tracepath -n 127.0.0.1`.", "Folge einem Boten von Leuchtturm zu Leuchtturm bis zu deinem eigenen Lager: `tracepath -n 127.0.0.1`.", "Segui un messaggero faro dopo faro fino al tuo campo: `tracepath -n 127.0.0.1`.", "Segue um mensageiro de farol em farol até ao teu acampamento: `tracepath -n 127.0.0.1`.", "Проследи за гонцом от маяка к маяку до своего лагеря: `tracepath -n 127.0.0.1`.", "跟着一名信使，一座灯塔一座灯塔地走到你自己的营地：`tracepath -n 127.0.0.1`。", "メッセンジャーを灯台から灯台へ、自分のキャンプまで追いかけよう：`tracepath -n 127.0.0.1`。", "एक संदेशवाहक के पीछे प्रकाशस्तंभ-दर-प्रकाशस्तंभ अपने ही शिविर तक चलो: `tracepath -n 127.0.0.1`।", "اتبع رسولًا من منارة إلى منارة حتى معسكرك: `tracepath -n 127.0.0.1`.", "এক বার্তাবাহকের পিছু পিছু বাতিঘর থেকে বাতিঘরে নিজের ক্যাম্প পর্যন্ত যাও: `tracepath -n 127.0.0.1`।", "Ikuti seorang pengantar dari mercusuar ke mercusuar sampai perkemahanmu sendiri: `tracepath -n 127.0.0.1`.", "ایک قاصد کے پیچھے لائٹ ہاؤس در لائٹ ہاؤس اپنے ہی کیمپ تک چلو: `tracepath -n 127.0.0.1`۔"),
 "hist.port9.1.bravo": T("Un seul saut : ton camp est juste là ! Vers un site lointain, tu verrais une dizaine de phares.", "Just one hop: your camp is right here! Towards a far-away site you'd see a dozen lighthouses.", "Un solo salto: ¡tu campamento está justo aquí! Hacia un sitio lejano verías una decena de faros.", "Nur ein Sprung: Dein Lager ist gleich hier! Zu einer fernen Seite sähest du etwa zehn Leuchttürme.", "Un solo salto: il tuo campo è proprio qui! Verso un sito lontano vedresti una decina di fari.", "Um só salto: o teu acampamento está mesmo aqui! Para um sítio distante verias uma dezena de faróis.", "Всего один прыжок: твой лагерь прямо здесь! До далёкого сайта ты увидел бы с десяток маяков.", "只有一跳：你的营地就在这儿！如果去一个很远的网站，你会看到十来座灯塔。", "1 回のジャンプだけ。キャンプはすぐそこ！遠いサイトなら灯台が 10 こくらい見えるよ。", "बस एक छलाँग: तुम्हारा शिविर यहीं है! किसी दूर की साइट तक तुम दस-एक प्रकाशस्तंभ देखते।", "قفزة واحدة فقط: معسكرك هنا! نحو موقع بعيد سترى نحو عشر منارات.", "মাত্র একটা লাফ: তোমার ক্যাম্প এখানেই! দূরের কোনো সাইটে গেলে দশটার মতো বাতিঘর দেখতে।", "Hanya satu lompatan: perkemahanmu tepat di sini! Ke situs yang jauh, kamu akan melihat belasan mercusuar.", "صرف ایک چھلانگ: تمہارا کیمپ یہیں ہے! کسی دور کی سائٹ تک تم دس کے قریب لائٹ ہاؤس دیکھتے۔"),
 "hist.port9.1.adulte": T("tracepath envoie des paquets à TTL croissant ; chaque routeur qui fait tomber le TTL à 0 répond, ce qui révèle le chemin. Vers un site public, seulement avec un adulte.", "tracepath sends packets with an increasing TTL; each router that brings the TTL down to 0 replies, which reveals the path. Towards a public site, only with an adult.", "tracepath envía paquetes con TTL creciente; cada router que deja el TTL en 0 responde, lo que revela el camino. Hacia un sitio público, solo con un adulto.", "tracepath sendet Pakete mit steigender TTL; jeder Router, der die TTL auf 0 bringt, antwortet und verrät so den Weg. Zu einer öffentlichen Seite nur mit einem Erwachsenen.", "tracepath invia pacchetti con TTL crescente; ogni router che porta il TTL a 0 risponde, svelando il percorso. Verso un sito pubblico, solo con un adulto.", "O tracepath envia pacotes com TTL crescente; cada router que leva o TTL a 0 responde, o que revela o caminho. Para um sítio público, só com um adulto.", "tracepath шлёт пакеты с растущим TTL; каждый маршрутизатор, обнуливший TTL, отвечает, и так виден путь. До публичного сайта — только со взрослым.", "tracepath 发送 TTL 逐渐增大的数据包；每个把 TTL 减到 0 的路由器都会回应，于是路径就显露出来。去公共网站时，要有大人陪着。", "tracepath は TTL をだんだん大きくしてパケットを送る。TTL を 0 にしたルーターが返事をするので、道すじがわかる。公開サイトに向けるのは大人といっしょのときだけ。", "tracepath बढ़ते TTL वाले पैकेट भेजता है; जो राउटर TTL को 0 करता है वह जवाब देता है, जिससे रास्ता दिखता है। सार्वजनिक साइट की ओर, सिर्फ़ किसी बड़े के साथ।", "يرسل tracepath حزمًا بقيمة TTL متزايدة؛ وكل موجّه يُنزل TTL إلى 0 يرد، فيظهر المسار. نحو موقع عام، فقط بصحبة شخص بالغ.", "tracepath ক্রমশ বাড়তে থাকা TTL-এর প্যাকেট পাঠায়; যে রাউটার TTL-কে ০ করে সে উত্তর দেয়, তাতে পথ দেখা যায়। পাবলিক সাইটের দিকে, শুধু বড়দের সঙ্গে।", "tracepath mengirim paket dengan TTL yang makin besar; setiap router yang membuat TTL jadi 0 membalas, sehingga jalurnya terlihat. Ke situs publik, hanya bersama orang dewasa.", "tracepath بڑھتے TTL والے پیکٹ بھیجتا ہے؛ جو راؤٹر TTL کو 0 کرتا ہے وہ جواب دیتا ہے، جس سے راستہ دکھتا ہے۔ عوامی سائٹ کی طرف، صرف کسی بڑے کے ساتھ۔"),
 "hist.port9.2.dit": T("Envoie un messager du camp jusqu'au biome Feu : `port messager feu`.", "Send a messenger from the camp to the Fire biome: `port messager feu`.", "Envía un mensajero del campamento al bioma Fuego: `port messager feu`.", "Schick einen Boten vom Lager zum Feuer-Biom: `port messager feu`.", "Manda un messaggero dal campo al bioma Fuoco: `port messager feu`.", "Manda um mensageiro do acampamento ao bioma Fogo: `port messager feu`.", "Отправь гонца из лагеря в биом Огня: `port messager feu`.", "从营地派一名信使到火之生物群落：`port messager feu`。", "キャンプから火のバイオームへメッセンジャーを送ろう：`port messager feu`。", "शिविर से आग के बायोम तक एक संदेशवाहक भेजो: `port messager feu`।", "أرسل رسولًا من المعسكر إلى منطقة النار: `port messager feu`.", "ক্যাম্প থেকে আগুনের বায়োমে একজন বার্তাবাহক পাঠাও: `port messager feu`।", "Kirim pengantar dari perkemahan ke bioma Api: `port messager feu`.", "کیمپ سے آگ کے بایوم تک ایک قاصد بھیجو: `port messager feu`۔"),
 "hist.port9.2.bravo": T("Camp → Racine → Roche → Feu : 3 sauts. À chaque phare, sa durée de vie (TTL) baisse de 1.", "Camp → Root → Rock → Fire: 3 hops. At each lighthouse its time to live (TTL) drops by 1.", "Campamento → Raíz → Roca → Fuego: 3 saltos. En cada faro su tiempo de vida (TTL) baja 1.", "Lager → Wurzel → Fels → Feuer: 3 Sprünge. An jedem Leuchtturm sinkt seine Lebensdauer (TTL) um 1.", "Campo → Radice → Roccia → Fuoco: 3 salti. A ogni faro il suo tempo di vita (TTL) scende di 1.", "Acampamento → Raiz → Rocha → Fogo: 3 saltos. Em cada farol o tempo de vida (TTL) desce 1.", "Лагерь → Корень → Скала → Огонь: 3 прыжка. На каждом маяке его время жизни (TTL) уменьшается на 1.", "营地 → 树根 → 岩石 → 火：3 跳。每过一座灯塔，它的生存时间（TTL）就减 1。", "キャンプ → 根っこ → 岩 → 火：3 ジャンプ。灯台を通るたびに寿命（TTL）が 1 へる。", "शिविर → जड़ → चट्टान → आग: 3 छलाँगें। हर प्रकाशस्तंभ पर उसकी आयु (TTL) 1 घटती है।", "المعسكر ← الجذر ← الصخر ← النار: 3 قفزات. عند كل منارة ينقص عمره (TTL) بواحد.", "ক্যাম্প → শিকড় → পাথর → আগুন: ৩টি লাফ। প্রতিটি বাতিঘরে তার আয়ু (TTL) ১ কমে।", "Perkemahan → Akar → Batu → Api: 3 lompatan. Di setiap mercusuar, masa hidupnya (TTL) turun 1.", "کیمپ ← جڑ ← چٹان ← آگ: 3 چھلانگیں۔ ہر لائٹ ہاؤس پر اس کی عمر (TTL) 1 کم ہوتی ہے۔"),
 "hist.port9.2.adulte": T("Chaque routeur choisit le prochain saut d'après sa table de routage et décrémente le TTL ; à 0, le paquet est détruit (pas de boucle sans fin).", "Each router picks the next hop from its routing table and decrements the TTL; at 0 the packet is dropped (no endless loop).", "Cada router elige el siguiente salto según su tabla de rutas y decrementa el TTL; en 0 el paquete se descarta (sin bucles infinitos).", "Jeder Router wählt den nächsten Sprung nach seiner Routingtabelle und verringert die TTL; bei 0 wird das Paket verworfen (keine Endlosschleife).", "Ogni router sceglie il salto successivo dalla sua tabella e decrementa il TTL; a 0 il pacchetto viene scartato (niente cicli infiniti).", "Cada router escolhe o próximo salto segundo a sua tabela e decrementa o TTL; a 0 o pacote é descartado (sem ciclos infinitos).", "Каждый маршрутизатор выбирает следующий прыжок по своей таблице и уменьшает TTL; при 0 пакет уничтожается (без бесконечных петель).", "每个路由器根据自己的路由表选择下一跳，并把 TTL 减 1；减到 0 时数据包被丢弃（不会无限绕圈）。", "ルーターはそれぞれルーティングテーブルで次のジャンプを選び、TTL を 1 へらす。0 になったパケットは捨てられる（終わらないループを防ぐ）。", "हर राउटर अपनी रूटिंग टेबल से अगली छलाँग चुनता है और TTL घटाता है; 0 पर पैकेट नष्ट हो जाता है (कोई अंतहीन चक्कर नहीं)।", "يختار كل موجّه القفزة التالية من جدوله وينقص TTL؛ عند 0 تُتلف الحزمة (فلا حلقة بلا نهاية).", "প্রতিটি রাউটার নিজের টেবিল দেখে পরের লাফ বেছে নেয় আর TTL কমায়; ০ হলে প্যাকেট নষ্ট হয় (অশেষ ঘোরাঘুরি নয়)।", "Setiap router memilih lompatan berikutnya dari tabelnya dan mengurangi TTL; pada 0 paket dibuang (tidak ada putaran tanpa akhir).", "ہر راؤٹر اپنی ٹیبل سے اگلی چھلانگ چنتا ہے اور TTL کم کرتا ہے؛ 0 پر پیکٹ ختم ہو جاتا ہے (کوئی نہ ختم ہونے والا چکر نہیں)۔"),
 "hist.port9.3.dit": T("Oh non, une tempête ! Éteins le phare de la Roche : `port eteins roche`.", "Oh no, a storm! Turn off the Rock lighthouse: `port eteins roche`.", "¡Oh no, una tormenta! Apaga el faro de la Roca: `port eteins roche`.", "Oh nein, ein Sturm! Schalte den Felsen-Leuchtturm aus: `port eteins roche`.", "Oh no, una tempesta! Spegni il faro della Roccia: `port eteins roche`.", "Oh não, uma tempestade! Apaga o farol da Rocha: `port eteins roche`.", "О нет, буря! Погаси маяк Скалы: `port eteins roche`.", "糟了，暴风雨！熄灭岩石灯塔：`port eteins roche`。", "たいへん、嵐だ！岩の灯台を消そう：`port eteins roche`。", "अरे नहीं, तूफ़ान! चट्टान का प्रकाशस्तंभ बुझाओ: `port eteins roche`।", "يا للهول، عاصفة! أطفئ منارة الصخر: `port eteins roche`.", "ওহ না, ঝড়! পাথরের বাতিঘর নিভিয়ে দাও: `port eteins roche`।", "Oh tidak, badai! Matikan mercusuar Batu: `port eteins roche`.", "ارے نہیں، طوفان! چٹان کا لائٹ ہاؤس بجھاؤ: `port eteins roche`۔"),
 "hist.port9.3.bravo": T("La Roche est dans le noir. Le chemin habituel vers Feu est coupé : il faut un détour.", "The Rock is in the dark. The usual path to Fire is cut: a detour is needed.", "La Roca está a oscuras. El camino habitual hacia Fuego está cortado: hace falta un desvío.", "Der Fels liegt im Dunkeln. Der übliche Weg zum Feuer ist unterbrochen: Ein Umweg muss her.", "La Roccia è al buio. La strada solita verso Fuoco è interrotta: serve una deviazione.", "A Rocha está às escuras. O caminho habitual para o Fogo está cortado: é preciso um desvio.", "Скала во тьме. Привычный путь к Огню перерезан: нужен обход.", "岩石陷入黑暗。去火的老路断了：得绕道。", "岩は真っ暗。火へのいつもの道が切れた。回り道が必要だ。", "चट्टान अँधेरे में है। आग तक का सामान्य रास्ता कट गया: घुमावदार रास्ता चाहिए।", "الصخر في الظلام. الطريق المعتاد إلى النار مقطوع: نحتاج إلى التفاف.", "পাথর অন্ধকারে। আগুনের দিকে চেনা পথ কাটা পড়ল: ঘুরপথ লাগবে।", "Batu dalam gelap. Jalan biasa ke Api terputus: perlu jalan memutar.", "چٹان اندھیرے میں ہے۔ آگ تک معمول کا راستہ کٹ گیا: لمبا راستہ چاہیے۔"),
 "hist.port9.3.adulte": T("Une panne de routeur rend une route invalide ; les protocoles de routage (OSPF, BGP…) recalculent un autre chemin s'il en existe un.", "A router failure makes a route invalid; routing protocols (OSPF, BGP…) compute another path if one exists.", "Un fallo de router invalida una ruta; los protocolos de enrutamiento (OSPF, BGP…) calculan otro camino si existe.", "Ein Routerausfall macht eine Route ungültig; Routingprotokolle (OSPF, BGP…) berechnen einen anderen Weg, falls es einen gibt.", "Un guasto di un router rende non valida una rotta; i protocolli di instradamento (OSPF, BGP…) calcolano un altro percorso se esiste.", "Uma avaria de router invalida uma rota; os protocolos de encaminhamento (OSPF, BGP…) calculam outro caminho se existir.", "Отказ маршрутизатора делает маршрут недействительным; протоколы маршрутизации (OSPF, BGP…) находят другой путь, если он есть.", "路由器故障会让一条路由失效；路由协议（OSPF、BGP 等）会在有其他路径时重新计算。", "ルーターがこわれると道が使えなくなる。ルーティングプロトコル（OSPF、BGP など）は、ほかの道があればそれを計算しなおす。", "राउटर की ख़राबी से एक रूट अमान्य हो जाता है; रूटिंग प्रोटोकॉल (OSPF, BGP…) कोई दूसरा रास्ता हो तो उसे निकालते हैं।", "عطل موجّه يُبطل مسارًا؛ وبروتوكولات التوجيه (OSPF و BGP…) تحسب طريقًا آخر إن وُجد.", "রাউটার বিকল হলে একটা রুট অচল হয়; রাউটিং প্রোটোকল (OSPF, BGP…) অন্য পথ থাকলে তা হিসাব করে।", "Kerusakan router membuat sebuah rute tidak berlaku; protokol perutean (OSPF, BGP…) menghitung jalur lain jika ada.", "راؤٹر کی خرابی سے ایک روٹ ناکارہ ہو جاتا ہے؛ روٹنگ پروٹوکول (OSPF، BGP…) کوئی اور راستہ ہو تو نکال لیتے ہیں۔"),
 "hist.port9.4.dit": T("Guide toi-même un messager jusqu'à Feu sans passer par la Roche. Regarde la carte, puis donne les phares dans l'ordre : `port guide racine … feu`.", "Guide a messenger to Fire yourself without going through the Rock. Look at the map, then give the lighthouses in order: `port guide racine … feu`.", "Guía tú mismo a un mensajero hasta Fuego sin pasar por la Roca. Mira el mapa y da los faros en orden: `port guide racine … feu`.", "Lotse selbst einen Boten zum Feuer, ohne über den Fels zu gehen. Schau auf die Karte und nenn die Leuchttürme der Reihe nach: `port guide racine … feu`.", "Guida tu un messaggero fino a Fuoco senza passare dalla Roccia. Guarda la mappa, poi dai i fari in ordine: `port guide racine … feu`.", "Guia tu um mensageiro até ao Fogo sem passar pela Rocha. Vê o mapa e dá os faróis por ordem: `port guide racine … feu`.", "Сам проведи гонца к Огню, минуя Скалу. Посмотри на карту и назови маяки по порядку: `port guide racine … feu`.", "自己引导一名信使去火，不经过岩石。看看地图，再按顺序说出灯塔：`port guide racine … feu`。", "岩を通らずに、自分でメッセンジャーを火まで案内しよう。地図を見て、灯台を順番に言ってね：`port guide racine … feu`。", "चट्टान से गुज़रे बिना ख़ुद एक संदेशवाहक को आग तक ले जाओ। नक्शा देखो, फिर प्रकाशस्तंभ क्रम से बताओ: `port guide racine … feu`।", "أرشد بنفسك رسولًا إلى النار دون المرور بالصخر. انظر إلى الخريطة ثم اذكر المنارات بالترتيب: `port guide racine … feu`.", "পাথর না ছুঁয়ে নিজেই একজন বার্তাবাহককে আগুন পর্যন্ত নিয়ে যাও। মানচিত্র দেখো, তারপর ক্রমে বাতিঘরগুলো বলো: `port guide racine … feu`।", "Pandu sendiri seorang pengantar ke Api tanpa melewati Batu. Lihat peta, lalu sebutkan mercusuar secara berurutan: `port guide racine … feu`.", "چٹان سے گزرے بغیر خود ایک قاصد کو آگ تک لے جاؤ۔ نقشہ دیکھو، پھر لائٹ ہاؤس ترتیب سے بتاؤ: `port guide racine … feu`۔"),
 "hist.port9.4.bravo": T("Arrivé sans perte ! Tu as trouvé le détour de phare en phare. Le chemin d'un paquet peut changer à chaque fois.", "Arrived without loss! You found the detour lighthouse by lighthouse. A packet's path can change every time.", "¡Llegó sin pérdidas! Encontraste el desvío faro a faro. El camino de un paquete puede cambiar cada vez.", "Ohne Verlust angekommen! Du hast den Umweg von Leuchtturm zu Leuchtturm gefunden. Der Weg eines Pakets kann sich jedes Mal ändern.", "Arrivato senza perdite! Hai trovato la deviazione faro dopo faro. Il percorso di un pacchetto può cambiare ogni volta.", "Chegou sem perdas! Encontraste o desvio de farol em farol. O caminho de um pacote pode mudar de cada vez.", "Дошёл без потерь! Ты нашёл обход от маяка к маяку. Путь пакета может меняться каждый раз.", "无损到达！你一座灯塔一座灯塔地找到了绕行路线。数据包的路径每次都可能不同。", "なくさずに到着！灯台から灯台へ、回り道を見つけたね。パケットの道は毎回かわることもある。", "बिना खोए पहुँच गया! तुमने प्रकाशस्तंभ-दर-प्रकाशस्तंभ घुमावदार रास्ता ढूँढ लिया। पैकेट का रास्ता हर बार बदल सकता है।", "وصل دون أن يضيع! وجدت الالتفاف من منارة إلى منارة. قد يتغير طريق الحزمة في كل مرة.", "কিছু না হারিয়ে পৌঁছাল! তুমি বাতিঘর থেকে বাতিঘরে ঘুরপথ খুঁজে পেলে। প্যাকেটের পথ প্রতিবার বদলাতে পারে।", "Tiba tanpa kehilangan! Kamu menemukan jalan memutar dari mercusuar ke mercusuar. Jalur paket bisa berubah setiap kali.", "بغیر کھوئے پہنچ گیا! تم نے لائٹ ہاؤس در لائٹ ہاؤس لمبا راستہ ڈھونڈ لیا۔ پیکٹ کا راستہ ہر بار بدل سکتا ہے۔"),
 "hist.port9.4.adulte": T("C'est un routage par la source : l'expéditeur fixe le chemin. Sur Internet, ce sont les routeurs qui choisissent, saut par saut.", "This is source routing: the sender sets the path. On the Internet, routers choose, hop by hop.", "Es un enrutamiento por origen: el remitente fija el camino. En Internet eligen los routers, salto a salto.", "Das ist Quellrouting: Der Absender legt den Weg fest. Im Internet entscheiden die Router, Sprung für Sprung.", "È un instradamento alla sorgente: il mittente fissa il percorso. Su Internet scelgono i router, salto dopo salto.", "É um encaminhamento pela origem: o remetente fixa o caminho. Na Internet, são os routers que escolhem, salto a salto.", "Это маршрутизация от источника: путь задаёт отправитель. В Интернете выбирают маршрутизаторы, прыжок за прыжком.", "这叫源路由：由发送者决定路径。在互联网上，是路由器一跳一跳地选择。", "これはソースルーティング：送る側が道を決める。インターネットでは、ルーターが 1 ジャンプずつ選ぶ。", "यह स्रोत-रूटिंग है: भेजने वाला रास्ता तय करता है। इंटरनेट पर राउटर छलाँग-दर-छलाँग चुनते हैं।", "هذا توجيه من المصدر: المرسل يحدد الطريق. على الإنترنت تختار الموجّهات قفزة بعد قفزة.", "এটা উৎস-রাউটিং: প্রেরক পথ ঠিক করে। ইন্টারনেটে রাউটারেরা লাফে লাফে বেছে নেয়।", "Ini perutean sumber: pengirim menentukan jalurnya. Di Internet, router yang memilih, lompatan demi lompatan.", "یہ سورس روٹنگ ہے: بھیجنے والا راستہ طے کرتا ہے۔ انٹرنیٹ پر راؤٹر چھلانگ در چھلانگ چنتے ہیں۔"),

 # ---- P10
 "hist.port10.0.dit": T("Qui est le gardien de ta maison ? Cherche la route par défaut : `ip route | grep default`.", "Who is the caretaker of your home? Find the default route: `ip route | grep default`.", "¿Quién es el conserje de tu casa? Busca la ruta por defecto: `ip route | grep default`.", "Wer ist der Hausmeister deines Zuhauses? Such die Standardroute: `ip route | grep default`.", "Chi è il portinaio di casa tua? Cerca la rotta predefinita: `ip route | grep default`.", "Quem é o porteiro da tua casa? Procura a rota por omissão: `ip route | grep default`.", "Кто консьерж твоего дома? Найди маршрут по умолчанию: `ip route | grep default`.", "你家的管理员是谁？找出默认路由：`ip route | grep default`。", "きみの家の管理人さんはだれ？デフォルトルートをさがそう：`ip route | grep default`。", "तुम्हारे घर का चौकीदार कौन है? डिफ़ॉल्ट रूट ढूँढो: `ip route | grep default`।", "من حارس بيتك؟ ابحث عن المسار الافتراضي: `ip route | grep default`.", "তোমার বাড়ির দারোয়ান কে? ডিফল্ট রুট খোঁজো: `ip route | grep default`।", "Siapa penjaga rumahmu? Cari rute bawaan: `ip route | grep default`.", "تمہارے گھر کا چوکیدار کون ہے؟ ڈیفالٹ روٹ ڈھونڈو: `ip route | grep default`۔"),
 "hist.port10.0.bravo": T("Cette adresse, c'est ta box (ou le routeur de l'école) : le gardien de l'immeuble.", "That address is your home router (or the school's): the building caretaker.", "Esa dirección es tu router de casa (o el del colegio): el conserje del edificio.", "Diese Adresse ist dein Router zu Hause (oder der der Schule): der Hausmeister.", "Quell'indirizzo è il tuo router di casa (o quello della scuola): il portinaio del palazzo.", "Esse endereço é o teu router de casa (ou o da escola): o porteiro do prédio.", "Этот адрес — твой домашний роутер (или школьный): консьерж дома.", "这个地址就是你家的路由器（或学校的）：大楼的管理员。", "そのアドレスが家のルーター（または学校のルーター）。マンションの管理人さんだ。", "यह पता तुम्हारे घर का राउटर है (या स्कूल का): इमारत का चौकीदार।", "هذا العنوان هو موجّه بيتك (أو موجّه المدرسة): حارس العمارة.", "এই ঠিকানা তোমার বাড়ির রাউটার (বা স্কুলের): বাড়ির দারোয়ান।", "Alamat itu adalah router rumahmu (atau sekolah): penjaga gedung.", "یہ پتہ تمہارے گھر کا راؤٹر ہے (یا اسکول کا): عمارت کا چوکیدار۔"),
 "hist.port10.0.adulte": T("La passerelle par défaut est en général la box, qui fait aussi serveur DHCP et NAT pour le réseau local.", "The default gateway is usually the home router, which is also the DHCP server and NAT for the local network.", "La pasarela por defecto suele ser el router de casa, que también hace de servidor DHCP y NAT para la red local.", "Das Standardgateway ist meist der Heimrouter, der auch DHCP-Server und NAT für das lokale Netz ist.", "Il gateway predefinito è di solito il router di casa, che fa anche da server DHCP e NAT per la rete locale.", "A porta de ligação por omissão é normalmente o router de casa, que também é servidor DHCP e NAT da rede local.", "Шлюз по умолчанию обычно домашний роутер; он же сервер DHCP и NAT для локальной сети.", "默认网关通常就是家里的路由器，它同时也是局域网的 DHCP 服务器和 NAT。", "デフォルトゲートウェイはたいてい家のルーターで、ローカルネットワークの DHCP サーバーと NAT も兼ねている。", "डिफ़ॉल्ट गेटवे आम तौर पर घर का राउटर होता है, जो स्थानीय नेटवर्क के लिए DHCP सर्वर और NAT भी है।", "البوابة الافتراضية عادةً هي موجّه البيت، وهو أيضًا خادم DHCP و NAT للشبكة المحلية.", "ডিফল্ট গেটওয়ে সাধারণত বাড়ির রাউটার, যা স্থানীয় নেটওয়ার্কের DHCP সার্ভার আর NAT-ও।", "Gateway bawaan biasanya router rumah, yang juga menjadi server DHCP dan NAT untuk jaringan lokal.", "ڈیفالٹ گیٹ وے عام طور پر گھر کا راؤٹر ہوتا ہے، جو مقامی نیٹ ورک کا DHCP سرور اور NAT بھی ہے۔"),
 "hist.port10.1.dit": T("Les voisins que ta machine connaît : `ip neigh`.", "The neighbours your machine knows: `ip neigh`.", "Los vecinos que conoce tu máquina: `ip neigh`.", "Die Nachbarn, die deine Maschine kennt: `ip neigh`.", "I vicini che la tua macchina conosce: `ip neigh`.", "Os vizinhos que a tua máquina conhece: `ip neigh`.", "Соседи, которых знает твоя машина: `ip neigh`.", "你的机器认识的邻居：`ip neigh`。", "きみのマシンが知っているご近所さん：`ip neigh`。", "पड़ोसी जिन्हें तुम्हारी मशीन जानती है: `ip neigh`।", "الجيران الذين تعرفهم آلتك: `ip neigh`.", "তোমার যন্ত্র যে প্রতিবেশীদের চেনে: `ip neigh`।", "Tetangga yang dikenal mesinmu: `ip neigh`.", "پڑوسی جنہیں تمہاری مشین جانتی ہے: `ip neigh`۔"),
 "hist.port10.1.bravo": T("Chaque ligne relie une adresse IP du réseau local à une adresse matérielle (MAC). Le gardien y est souvent.", "Each line links an IP address on the local network to a hardware (MAC) address. The caretaker is often there.", "Cada línea une una dirección IP de la red local con una dirección física (MAC). El conserje suele estar ahí.", "Jede Zeile verbindet eine IP-Adresse im lokalen Netz mit einer Hardware-Adresse (MAC). Der Hausmeister steht oft dabei.", "Ogni riga collega un indirizzo IP della rete locale a un indirizzo fisico (MAC). Il portinaio spesso c'è.", "Cada linha liga um endereço IP da rede local a um endereço físico (MAC). O porteiro costuma lá estar.", "Каждая строка связывает IP-адрес локальной сети с аппаратным (MAC) адресом. Консьерж часто там есть.", "每一行把局域网里的一个 IP 地址和一个硬件（MAC）地址连起来。管理员经常也在里面。", "各行はローカルネットワークの IP アドレスと機械の住所（MAC アドレス）を結ぶ。管理人さんもよくいるよ。", "हर पंक्ति स्थानीय नेटवर्क के एक IP पते को एक हार्डवेयर (MAC) पते से जोड़ती है। चौकीदार अक्सर इसमें होता है।", "كل سطر يربط عنوان IP في الشبكة المحلية بعنوان مادي (MAC). وغالبًا ما يكون الحارس بينها.", "প্রতিটি লাইন স্থানীয় নেটওয়ার্কের একটা IP ঠিকানাকে একটা যন্ত্র-ঠিকানার (MAC) সঙ্গে জোড়ে। দারোয়ান প্রায়ই সেখানে থাকে।", "Setiap baris menghubungkan alamat IP jaringan lokal dengan alamat perangkat keras (MAC). Penjaga sering ada di sana.", "ہر سطر مقامی نیٹ ورک کے ایک IP پتے کو ایک ہارڈویئر (MAC) پتے سے جوڑتی ہے۔ چوکیدار اکثر وہاں ہوتا ہے۔"),
 "hist.port10.1.adulte": T("`ip neigh` affiche la table ARP/NDP : la correspondance IP ↔ adresse MAC des voisins directs. Une adresse MAC ne sort pas du réseau local.", "`ip neigh` shows the ARP/NDP table: the IP ↔ MAC address mapping of direct neighbours. A MAC address never leaves the local network.", "`ip neigh` muestra la tabla ARP/NDP: la correspondencia IP ↔ MAC de los vecinos directos. Una dirección MAC no sale de la red local.", "`ip neigh` zeigt die ARP/NDP-Tabelle: die Zuordnung IP ↔ MAC-Adresse der direkten Nachbarn. Eine MAC-Adresse verlässt das lokale Netz nicht.", "`ip neigh` mostra la tabella ARP/NDP: la corrispondenza IP ↔ MAC dei vicini diretti. Un indirizzo MAC non esce dalla rete locale.", "`ip neigh` mostra a tabela ARP/NDP: a correspondência IP ↔ MAC dos vizinhos diretos. Um endereço MAC não sai da rede local.", "`ip neigh` показывает таблицу ARP/NDP: соответствие IP ↔ MAC-адрес прямых соседей. MAC-адрес не выходит за пределы локальной сети.", "`ip neigh` 显示 ARP/NDP 表：直接邻居的 IP ↔ MAC 地址对应关系。MAC 地址不会离开局域网。", "`ip neigh` は ARP/NDP テーブルを表示する：直接のご近所の IP ↔ MAC アドレスの対応。MAC アドレスはローカルネットワークの外に出ない。", "`ip neigh` ARP/NDP टेबल दिखाता है: सीधे पड़ोसियों का IP ↔ MAC पता मेल। MAC पता स्थानीय नेटवर्क से बाहर नहीं जाता।", "يعرض `ip neigh` جدول ARP/NDP: مطابقة IP ↔ عنوان MAC للجيران المباشرين. عنوان MAC لا يغادر الشبكة المحلية.", "`ip neigh` ARP/NDP টেবিল দেখায়: সরাসরি প্রতিবেশীদের IP ↔ MAC ঠিকানার মিল। MAC ঠিকানা স্থানীয় নেটওয়ার্কের বাইরে যায় না।", "`ip neigh` menampilkan tabel ARP/NDP: pemetaan IP ↔ alamat MAC tetangga langsung. Alamat MAC tidak keluar dari jaringan lokal.", "`ip neigh` ARP/NDP ٹیبل دکھاتا ہے: براہ راست پڑوسیوں کا IP ↔ MAC پتہ۔ MAC پتہ مقامی نیٹ ورک سے باہر نہیں جاتا۔"),
 "hist.port10.2.dit": T("Regarde le gardien accueillir de nouveaux appareils : `port gardien`.", "Watch the caretaker welcome new devices: `port gardien`.", "Mira al conserje recibir aparatos nuevos: `port gardien`.", "Sieh zu, wie der Hausmeister neue Geräte empfängt: `port gardien`.", "Guarda il portinaio accogliere nuovi dispositivi: `port gardien`.", "Vê o porteiro receber aparelhos novos: `port gardien`.", "Посмотри, как консьерж встречает новые устройства: `port gardien`.", "看看管理员怎样接待新设备：`port gardien`。", "管理人さんが新しい機械をむかえるところを見よう：`port gardien`。", "चौकीदार को नए उपकरणों का स्वागत करते देखो: `port gardien`।", "شاهد الحارس يستقبل أجهزة جديدة: `port gardien`.", "দেখো দারোয়ান কীভাবে নতুন যন্ত্রদের স্বাগত জানায়: `port gardien`।", "Lihat penjaga menyambut perangkat baru: `port gardien`.", "چوکیدار کو نئے آلات کا استقبال کرتے دیکھو: `port gardien`۔"),
 "hist.port10.2.bravo": T("Le gardien donne un numéro d'appartement à chacun (DHCP) et poste tout le courrier avec l'adresse de l'immeuble (NAT).", "The caretaker gives each one a flat number (DHCP) and posts all the mail with the building's address (NAT).", "El conserje da a cada uno un número de piso (DHCP) y envía todo el correo con la dirección del edificio (NAT).", "Der Hausmeister gibt jedem eine Wohnungsnummer (DHCP) und schickt alle Post mit der Adresse des Hauses ab (NAT).", "Il portinaio dà a ciascuno un numero di appartamento (DHCP) e spedisce tutta la posta con l'indirizzo del palazzo (NAT).", "O porteiro dá a cada um um número de apartamento (DHCP) e envia todo o correio com o endereço do prédio (NAT).", "Консьерж даёт каждому номер квартиры (DHCP) и отправляет всю почту с адресом дома (NAT).", "管理员给每台设备一个房间号（DHCP），并用大楼的地址寄出所有信件（NAT）。", "管理人さんは、ひとつずつ部屋番号をわたし（DHCP）、郵便はぜんぶマンションの住所で出す（NAT）。", "चौकीदार हर एक को फ़्लैट-नंबर देता है (DHCP) और सारी डाक इमारत के पते से भेजता है (NAT)।", "يعطي الحارس كل واحد رقم شقة (DHCP) ويرسل كل البريد بعنوان العمارة (NAT).", "দারোয়ান প্রত্যেককে একটা ফ্ল্যাট নম্বর দেয় (DHCP) আর সব চিঠি বাড়ির ঠিকানায় পাঠায় (NAT)।", "Penjaga memberi setiap perangkat nomor apartemen (DHCP) dan mengirim semua surat dengan alamat gedung (NAT).", "چوکیدار ہر ایک کو فلیٹ نمبر دیتا ہے (DHCP) اور ساری ڈاک عمارت کے پتے سے بھیجتا ہے (NAT)۔"),
 "hist.port10.2.adulte": T("DHCP distribue des adresses privées (192.168.x.x, RFC 1918) ; le NAT les traduit en une seule adresse publique. 203.0.113.7 est une adresse réservée à la documentation.", "DHCP hands out private addresses (192.168.x.x, RFC 1918); NAT translates them into a single public address. 203.0.113.7 is an address reserved for documentation.", "DHCP reparte direcciones privadas (192.168.x.x, RFC 1918); el NAT las traduce a una única dirección pública. 203.0.113.7 es una dirección reservada para documentación.", "DHCP verteilt private Adressen (192.168.x.x, RFC 1918); NAT übersetzt sie in eine einzige öffentliche Adresse. 203.0.113.7 ist eine für Dokumentation reservierte Adresse.", "DHCP distribuisce indirizzi privati (192.168.x.x, RFC 1918); il NAT li traduce in un solo indirizzo pubblico. 203.0.113.7 è un indirizzo riservato alla documentazione.", "O DHCP distribui endereços privados (192.168.x.x, RFC 1918); o NAT traduz-os num só endereço público. 203.0.113.7 é um endereço reservado à documentação.", "DHCP раздаёт частные адреса (192.168.x.x, RFC 1918); NAT переводит их в один публичный адрес. 203.0.113.7 — адрес, зарезервированный для документации.", "DHCP 分发私有地址（192.168.x.x，RFC 1918）；NAT 把它们转换成一个公网地址。203.0.113.7 是保留给文档示例用的地址。", "DHCP はプライベートアドレス（192.168.x.x、RFC 1918）を配り、NAT はそれをひとつのパブリックアドレスに変える。203.0.113.7 は説明用に予約されたアドレス。", "DHCP निजी पते (192.168.x.x, RFC 1918) बाँटता है; NAT उन्हें एक ही सार्वजनिक पते में बदलता है। 203.0.113.7 दस्तावेज़ों के लिए आरक्षित पता है।", "يوزّع DHCP عناوين خاصة (192.168.x.x، RFC 1918)؛ ويترجمها NAT إلى عنوان عام واحد. العنوان 203.0.113.7 محجوز للتوثيق.", "DHCP ব্যক্তিগত ঠিকানা (192.168.x.x, RFC 1918) বিলি করে; NAT সেগুলোকে একটাই সর্বজনীন ঠিকানায় বদলায়। 203.0.113.7 নথিপত্রের জন্য সংরক্ষিত ঠিকানা।", "DHCP membagikan alamat privat (192.168.x.x, RFC 1918); NAT menerjemahkannya menjadi satu alamat publik. 203.0.113.7 adalah alamat yang dicadangkan untuk dokumentasi.", "DHCP نجی پتے (192.168.x.x، RFC 1918) بانٹتا ہے؛ NAT انہیں ایک ہی عوامی پتے میں بدلتا ہے۔ 203.0.113.7 دستاویزات کے لیے مخصوص پتہ ہے۔"),

 # ---- P11
 "hist.port11.0.dit": T("Le phare a aussi une porte scellée, en https. Frappe : `curl https://localhost:8443`.", "The lighthouse also has a sealed door, over https. Knock: `curl https://localhost:8443`.", "El faro también tiene una puerta sellada, en https. Llama: `curl https://localhost:8443`.", "Der Leuchtturm hat auch eine versiegelte Tür, über https. Klopf an: `curl https://localhost:8443`.", "Il faro ha anche una porta sigillata, in https. Bussa: `curl https://localhost:8443`.", "O farol também tem uma porta selada, em https. Bate: `curl https://localhost:8443`.", "У маяка есть и запечатанная дверь, по https. Постучи: `curl https://localhost:8443`.", "灯塔还有一扇封印的门，用 https。敲敲门：`curl https://localhost:8443`。", "灯台には https の封印されたドアもある。ノックしよう：`curl https://localhost:8443`。", "प्रकाशस्तंभ का एक मुहरबंद दरवाज़ा भी है, https पर। दस्तक दो: `curl https://localhost:8443`।", "للمنارة أيضًا باب مختوم عبر https. اطرق: `curl https://localhost:8443`.", "বাতিঘরের একটা সিলমোহর করা দরজাও আছে, https-এ। কড়া নাড়ো: `curl https://localhost:8443`।", "Mercusuar juga punya pintu bersegel, lewat https. Ketuk: `curl https://localhost:8443`.", "لائٹ ہاؤس کا ایک مہر بند دروازہ بھی ہے، https پر۔ دستک دو: `curl https://localhost:8443`۔"),
 "hist.port11.0.bravo": T("curl refuse : « self-signed certificate ». Le sceau a été signé par le phare lui-même : personne ne s'en porte garant.", "curl refuses: \"self-signed certificate\". The seal was signed by the lighthouse itself: nobody vouches for it.", "curl se niega: «self-signed certificate». El sello lo firmó el propio faro: nadie responde por él.", "curl weigert sich: „self-signed certificate“. Das Siegel hat der Leuchtturm selbst unterschrieben: Niemand bürgt dafür.", "curl rifiuta: «self-signed certificate». Il sigillo l'ha firmato il faro stesso: nessuno ne garantisce.", "O curl recusa: «self-signed certificate». O selo foi assinado pelo próprio farol: ninguém se responsabiliza por ele.", "curl отказывается: «self-signed certificate». Печать подписал сам маяк: никто за неё не ручается.", "curl 拒绝了：「self-signed certificate」。这个封印是灯塔自己签的：没有人为它担保。", "curl はことわった：「self-signed certificate」。封印は灯台が自分でサインしたもので、だれも保証していない。", "curl मना करता है: «self-signed certificate»। मुहर पर प्रकाशस्तंभ ने ख़ुद हस्ताक्षर किए: कोई इसकी गारंटी नहीं देता।", "يرفض curl: «self-signed certificate». وقّعت المنارة الختم بنفسها: لا أحد يضمنه.", "curl রাজি নয়: «self-signed certificate»। সিলমোহরে বাতিঘর নিজেই সই করেছে: কেউ এর দায় নেয় না।", "curl menolak: \"self-signed certificate\". Segelnya ditandatangani mercusuar sendiri: tidak ada yang menjaminnya.", "curl انکار کرتا ہے: «self-signed certificate»۔ مہر پر لائٹ ہاؤس نے خود دستخط کیے: کوئی اس کی ضمانت نہیں دیتا۔"),
 "hist.port11.0.adulte": T("En HTTPS, le serveur présente un certificat ; curl vérifie qu'il est signé par une autorité de confiance et qu'il porte le bon nom. Un certificat auto-signé échoue (erreur 60).", "With HTTPS the server presents a certificate; curl checks it is signed by a trusted authority and carries the right name. A self-signed certificate fails (error 60).", "En HTTPS el servidor presenta un certificado; curl comprueba que lo firma una autoridad de confianza y que lleva el nombre correcto. Uno autofirmado falla (error 60).", "Bei HTTPS legt der Server ein Zertifikat vor; curl prüft, ob es von einer vertrauenswürdigen Stelle signiert ist und den richtigen Namen trägt. Ein selbstsigniertes scheitert (Fehler 60).", "In HTTPS il server presenta un certificato; curl verifica che sia firmato da un'autorità fidata e che porti il nome giusto. Uno autofirmato fallisce (errore 60).", "Em HTTPS o servidor apresenta um certificado; o curl verifica se é assinado por uma autoridade de confiança e se tem o nome certo. Um autoassinado falha (erro 60).", "В HTTPS сервер предъявляет сертификат; curl проверяет, что его подписал доверенный центр и что в нём правильное имя. Самоподписанный не проходит (ошибка 60).", "在 HTTPS 中，服务器出示证书；curl 检查它是否由受信任的机构签发、名字是否正确。自签名证书会失败（错误 60）。", "HTTPS ではサーバーが証明書を見せる。curl は、信頼できる認証局の署名があるか、名前が正しいかを確かめる。自己署名の証明書は失敗する（エラー 60）。", "HTTPS में सर्वर एक प्रमाणपत्र दिखाता है; curl जाँचता है कि वह किसी भरोसेमंद प्राधिकरण से हस्ताक्षरित है और सही नाम वाला है। स्व-हस्ताक्षरित प्रमाणपत्र विफल होता है (त्रुटि 60)।", "في HTTPS يقدّم الخادم شهادة؛ ويتحقق curl من أنها موقّعة من جهة موثوقة وتحمل الاسم الصحيح. الشهادة الموقّعة ذاتيًا تفشل (الخطأ 60).", "HTTPS-এ সার্ভার একটা সার্টিফিকেট দেখায়; curl যাচাই করে সেটা কোনো বিশ্বস্ত কর্তৃপক্ষের সই করা কিনা আর নাম ঠিক কিনা। নিজে-সই করা সার্টিফিকেট ব্যর্থ হয় (ত্রুটি 60)।", "Dengan HTTPS, server menunjukkan sertifikat; curl memeriksa apakah ditandatangani otoritas tepercaya dan bernama benar. Sertifikat yang ditandatangani sendiri gagal (galat 60).", "HTTPS میں سرور ایک سرٹیفکیٹ دکھاتا ہے؛ curl جانچتا ہے کہ وہ کسی قابل اعتماد ادارے کا دستخط شدہ ہے اور صحیح نام والا ہے۔ خود دستخط شدہ سرٹیفکیٹ ناکام ہوتا ہے (غلطی 60)۔"),
 "hist.port11.1.dit": T("Le notaire du port t'a confié le sceau du phare. Dis à curl de lui faire confiance : `curl --cacert sceau_du_phare.pem https://localhost:8443`.", "The harbour notary gave you the lighthouse's seal. Tell curl to trust it: `curl --cacert sceau_du_phare.pem https://localhost:8443`.", "El notario del puerto te confió el sello del faro. Dile a curl que confíe en él: `curl --cacert sceau_du_phare.pem https://localhost:8443`.", "Der Hafennotar hat dir das Siegel des Leuchtturms anvertraut. Sag curl, dass es ihm trauen soll: `curl --cacert sceau_du_phare.pem https://localhost:8443`.", "Il notaio del porto ti ha affidato il sigillo del faro. Di' a curl di fidarsi: `curl --cacert sceau_du_phare.pem https://localhost:8443`.", "O notário do porto confiou-te o selo do farol. Diz ao curl para confiar nele: `curl --cacert sceau_du_phare.pem https://localhost:8443`.", "Нотариус порта доверил тебе печать маяка. Скажи curl, что ей можно верить: `curl --cacert sceau_du_phare.pem https://localhost:8443`.", "港口公证人把灯塔的封印交给了你。告诉 curl 信任它：`curl --cacert sceau_du_phare.pem https://localhost:8443`。", "港の公証人が灯台の封印をあずけてくれた。curl に信用するよう伝えよう：`curl --cacert sceau_du_phare.pem https://localhost:8443`。", "बंदरगाह के नोटरी ने तुम्हें प्रकाशस्तंभ की मुहर सौंपी है। curl से कहो कि उस पर भरोसा करे: `curl --cacert sceau_du_phare.pem https://localhost:8443`।", "سلّمك موثّق الميناء ختم المنارة. قل لـ curl أن يثق به: `curl --cacert sceau_du_phare.pem https://localhost:8443`.", "বন্দরের নোটারি তোমাকে বাতিঘরের সিলমোহর দিয়েছে। curl-কে বলো ওটাকে বিশ্বাস করতে: `curl --cacert sceau_du_phare.pem https://localhost:8443`।", "Notaris pelabuhan menitipkan segel mercusuar kepadamu. Suruh curl memercayainya: `curl --cacert sceau_du_phare.pem https://localhost:8443`.", "بندرگاہ کے نوٹری نے تمہیں لائٹ ہاؤس کی مہر سونپی ہے۔ curl سے کہو کہ اس پر بھروسا کرے: `curl --cacert sceau_du_phare.pem https://localhost:8443`۔"),
 "hist.port11.1.bravo": T("Cette fois la porte s'ouvre : le sceau correspond à celui que tu connais. La lettre a voyagé chiffrée.", "This time the door opens: the seal matches the one you know. The letter travelled encrypted.", "Esta vez la puerta se abre: el sello coincide con el que conoces. La carta viajó cifrada.", "Diesmal geht die Tür auf: Das Siegel passt zu dem, das du kennst. Der Brief ist verschlüsselt gereist.", "Stavolta la porta si apre: il sigillo corrisponde a quello che conosci. La lettera ha viaggiato cifrata.", "Desta vez a porta abre-se: o selo corresponde ao que conheces. A carta viajou cifrada.", "На этот раз дверь открывается: печать совпадает с той, что ты знаешь. Письмо ехало зашифрованным.", "这次门开了：封印和你认识的那个一模一样。信是加密着送来的。", "こんどはドアが開いた。封印がきみの知っているものと一致したんだ。手紙は暗号化されて届いたよ。", "इस बार दरवाज़ा खुल गया: मुहर उसी से मेल खाती है जिसे तुम जानते हो। चिट्ठी कूट रूप में आई।", "هذه المرة انفتح الباب: الختم يطابق الذي تعرفه. سافرت الرسالة مشفّرة.", "এবার দরজা খুলল: সিলমোহরটা তোমার চেনাটার সঙ্গে মিলে গেছে। চিঠি এনক্রিপ্ট হয়ে এসেছে।", "Kali ini pintunya terbuka: segelnya cocok dengan yang kamu kenal. Suratnya bepergian dalam keadaan terenkripsi.", "اس بار دروازہ کھل گیا: مہر اسی سے ملتی ہے جسے تم جانتے ہو۔ خط خفیہ شکل میں آیا۔"),
 "hist.port11.1.adulte": T("--cacert remplace les autorités connues par ce certificat. On ne fait confiance à un certificat que si on l'a reçu par un chemin sûr.", "--cacert replaces the known authorities with this certificate. Only trust a certificate you received through a safe channel.", "--cacert sustituye las autoridades conocidas por este certificado. Solo se confía en un certificado recibido por un canal seguro.", "--cacert ersetzt die bekannten Stellen durch dieses Zertifikat. Man vertraut nur einem Zertifikat, das man auf sicherem Weg bekommen hat.", "--cacert sostituisce le autorità note con questo certificato. Ci si fida solo di un certificato ricevuto per una via sicura.", "--cacert substitui as autoridades conhecidas por este certificado. Só se confia num certificado recebido por um caminho seguro.", "--cacert заменяет известные центры этим сертификатом. Доверять можно только сертификату, полученному надёжным путём.", "--cacert 用这张证书替换已知的机构。只有通过安全渠道拿到的证书才能信任。", "--cacert は、知っている認証局のかわりにこの証明書を使う。安全な道で受け取った証明書だけを信用しよう。", "--cacert जाने-पहचाने प्राधिकरणों की जगह यह प्रमाणपत्र रखता है। प्रमाणपत्र पर तभी भरोसा करो जब वह सुरक्षित रास्ते से मिला हो।", "يستبدل --cacert الجهات المعروفة بهذه الشهادة. لا نثق بشهادة إلا إذا وصلتنا عبر طريق آمن.", "--cacert চেনা কর্তৃপক্ষের বদলে এই সার্টিফিকেট ব্যবহার করে। নিরাপদ পথে পাওয়া সার্টিফিকেটই শুধু বিশ্বাস করা যায়।", "--cacert mengganti otoritas yang dikenal dengan sertifikat ini. Percayai sertifikat hanya jika diterima lewat jalur yang aman.", "--cacert جانے پہچانے اداروں کی جگہ یہ سرٹیفکیٹ رکھتا ہے۔ سرٹیفکیٹ پر تبھی بھروسا کرو جب وہ محفوظ راستے سے ملا ہو۔"),
 "hist.port11.2.dit": T("Le notaire te montre 4 sceaux. Lis-les bien : `port sceau`.", "The notary shows you 4 seals. Read them carefully: `port sceau`.", "El notario te enseña 4 sellos. Léelos bien: `port sceau`.", "Der Notar zeigt dir 4 Siegel. Lies sie gut: `port sceau`.", "Il notaio ti mostra 4 sigilli. Leggili bene: `port sceau`.", "O notário mostra-te 4 selos. Lê-os bem: `port sceau`.", "Нотариус показывает тебе 4 печати. Прочитай их внимательно: `port sceau`.", "公证人给你看 4 个封印。仔细读一读：`port sceau`。", "公証人が封印を 4 つ見せてくれる。よく読んでね：`port sceau`。", "नोटरी तुम्हें 4 मुहरें दिखाता है। ध्यान से पढ़ो: `port sceau`।", "يُريك الموثّق 4 أختام. اقرأها جيدًا: `port sceau`.", "নোটারি তোমাকে ৪টি সিলমোহর দেখায়। মন দিয়ে পড়ো: `port sceau`।", "Notaris menunjukkan 4 segel. Baca dengan teliti: `port sceau`.", "نوٹری تمہیں 4 مہریں دکھاتا ہے۔ غور سے پڑھو: `port sceau`۔"),
 "hist.port11.2.bravo": T("Regarde qui a signé, pour quel nom, et la date.", "Look at who signed, for which name, and the date.", "Fíjate en quién firmó, para qué nombre y la fecha.", "Achte darauf, wer unterschrieben hat, für welchen Namen und das Datum.", "Guarda chi ha firmato, per quale nome, e la data.", "Repara em quem assinou, para que nome e a data.", "Смотри, кто подписал, на какое имя и какая дата.", "看看是谁签的、给哪个名字签的，还有日期。", "だれがサインしたか、どの名前あてか、日付はどうか見てみよう。", "देखो किसने हस्ताक्षर किए, किस नाम के लिए, और तारीख़ क्या है।", "انظر من وقّع، ولأي اسم، والتاريخ.", "দেখো কে সই করেছে, কোন নামের জন্য, আর তারিখ।", "Lihat siapa yang menandatangani, untuk nama apa, dan tanggalnya.", "دیکھو کس نے دستخط کیے، کس نام کے لیے، اور تاریخ کیا ہے۔"),
 "hist.port11.2.adulte": T("Un certificat valable : signé par une autorité reconnue, au nom exact du site, dans sa période de validité.", "A valid certificate: signed by a recognised authority, for the exact site name, within its validity period.", "Un certificado válido: firmado por una autoridad reconocida, con el nombre exacto del sitio, dentro de su periodo de validez.", "Ein gültiges Zertifikat: von einer anerkannten Stelle signiert, auf den genauen Namen der Seite, innerhalb seiner Gültigkeit.", "Un certificato valido: firmato da un'autorità riconosciuta, a nome esatto del sito, entro il periodo di validità.", "Um certificado válido: assinado por uma autoridade reconhecida, com o nome exato do sítio, dentro do prazo de validade.", "Действительный сертификат: подписан признанным центром, на точное имя сайта, в пределах срока действия.", "有效的证书：由公认的机构签发、名字与网站完全一致、在有效期内。", "有効な証明書とは：認められた認証局の署名があり、サイトの名前がぴったり合い、有効期限内であること。", "मान्य प्रमाणपत्र: किसी मान्यता-प्राप्त प्राधिकरण से हस्ताक्षरित, साइट के सटीक नाम पर, अपनी वैधता अवधि के भीतर।", "الشهادة الصالحة: موقّعة من جهة معترف بها، باسم الموقع بالضبط، وضمن مدة صلاحيتها.", "বৈধ সার্টিফিকেট: স্বীকৃত কর্তৃপক্ষের সই, সাইটের হুবহু নামে, মেয়াদের মধ্যে।", "Sertifikat yang sah: ditandatangani otoritas yang diakui, atas nama situs yang tepat, dalam masa berlakunya.", "درست سرٹیفکیٹ: کسی تسلیم شدہ ادارے کا دستخط شدہ، سائٹ کے بالکل صحیح نام پر، اپنی مدت کے اندر۔"),
 "hist.port11.3.dit": T("Lequel est le vrai sceau ? Donne son numéro : `port sceau ?`.", "Which one is the real seal? Give its number: `port sceau ?`.", "¿Cuál es el sello verdadero? Da su número: `port sceau ?`.", "Welches ist das echte Siegel? Nenn seine Nummer: `port sceau ?`.", "Qual è il vero sigillo? Dai il suo numero: `port sceau ?`.", "Qual é o selo verdadeiro? Dá o número dele: `port sceau ?`.", "Какая печать настоящая? Назови её номер: `port sceau ?`.", "哪一个才是真的封印？说出它的号码：`port sceau ?`。", "本物の封印はどれ？番号を言ってね：`port sceau ?`。", "असली मुहर कौन-सी है? उसका नंबर बताओ: `port sceau ?`।", "أي واحد هو الختم الحقيقي؟ اذكر رقمه: `port sceau ?`.", "কোনটা আসল সিলমোহর? তার নম্বর বলো: `port sceau ?`।", "Mana segel yang asli? Sebutkan nomornya: `port sceau ?`.", "اصلی مہر کون سی ہے؟ اس کا نمبر بتاؤ: `port sceau ?`۔"),
 "hist.port11.3.bravo": T("Bien vu ! Le cadenas prouve à QUI tu parles, pas que ce qu'il dit est vrai.", "Well spotted! The padlock proves WHO you're talking to, not that what it says is true.", "¡Bien visto! El candado prueba con QUIÉN hablas, no que lo que dice sea verdad.", "Gut erkannt! Das Schloss beweist, mit WEM du sprichst, nicht dass stimmt, was er sagt.", "Ben visto! Il lucchetto prova con CHI parli, non che quello che dice sia vero.", "Bem visto! O cadeado prova com QUEM falas, não que o que diz seja verdade.", "Верно! Замок доказывает, С КЕМ ты говоришь, но не то, что он говорит правду.", "眼力真好！小锁证明的是你在和「谁」说话，并不证明它说的都是真的。", "よく見つけたね！南京錠は、きみが「だれと」話しているかを証明する。言っていることが本当かどうかではないよ。", "बढ़िया पहचाना! ताला साबित करता है कि तुम «किससे» बात कर रहे हो, यह नहीं कि वह जो कहता है वह सच है।", "أحسنت! يثبت القفل «مع من» تتحدث، لا أن ما يقوله صحيح.", "ঠিক ধরেছ! তালা প্রমাণ করে তুমি «কার» সঙ্গে কথা বলছ, সে যা বলে তা সত্যি কিনা নয়।", "Jeli! Gembok membuktikan dengan SIAPA kamu berbicara, bukan bahwa yang dikatakannya benar.", "خوب پہچانا! تالا ثابت کرتا ہے کہ تم «کس سے» بات کر رہے ہو، یہ نہیں کہ وہ جو کہتا ہے سچ ہے۔"),
 "hist.port11.3.adulte": T("TLS garantit l'authenticité du serveur et la confidentialité du trajet ; il ne dit rien de l'honnêteté du site.", "TLS guarantees the server's authenticity and the confidentiality of the trip; it says nothing about the site's honesty.", "TLS garantiza la autenticidad del servidor y la confidencialidad del trayecto; no dice nada de la honradez del sitio.", "TLS garantiert die Echtheit des Servers und die Vertraulichkeit des Wegs; über die Ehrlichkeit der Seite sagt es nichts.", "TLS garantisce l'autenticità del server e la riservatezza del tragitto; non dice nulla sull'onestà del sito.", "O TLS garante a autenticidade do servidor e a confidencialidade do trajeto; não diz nada sobre a honestidade do sítio.", "TLS гарантирует подлинность сервера и тайну пути; о честности сайта он ничего не говорит.", "TLS 保证服务器是真的、传输过程是保密的；它不说明网站是否诚实。", "TLS が保証するのはサーバーが本物であることと、途中の内容がひみつであること。サイトが正直かどうかは何も言わない。", "TLS सर्वर की प्रामाणिकता और रास्ते की गोपनीयता की गारंटी देता है; साइट की ईमानदारी के बारे में कुछ नहीं कहता।", "يضمن TLS أصالة الخادم وسرية الطريق؛ ولا يقول شيئًا عن نزاهة الموقع.", "TLS সার্ভারের সত্যতা আর পথের গোপনীয়তা নিশ্চিত করে; সাইটের সততা নিয়ে কিছু বলে না।", "TLS menjamin keaslian server dan kerahasiaan perjalanan; ia tidak mengatakan apa pun tentang kejujuran situs.", "TLS سرور کی اصلیت اور راستے کی رازداری کی ضمانت دیتا ہے؛ سائٹ کی ایمانداری کے بارے میں کچھ نہیں کہتا۔"),
}
